package com.codex.loginsight;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexLogInsightPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexLogInsightPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.loginsight;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexLogInsightConfig.GROUP)
public interface CodexLogInsightConfig extends Config
{
	String GROUP = "codexloginsight";

	enum Rates
	{
		AUTO("Match my account"),
		MAIN("Normal account"),
		IRON("Ironman");

		private final String label;

		Rates(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "New slots",
		description = "What Log Insight does when a new collection log slot drops",
		position = 0
	)
	String finds = "finds";

	@ConfigSection(
		name = "Estimates",
		description = "How Log Insight estimates time",
		position = 1
	)
	String estimates = "estimates";

	@ConfigItem(
		keyName = "showPlaque",
		name = "Show plaque",
		description = "Show a plaque in the game view with the slot's odds and how lucky it was",
		position = 1,
		section = finds
	)
	default boolean showPlaque()
	{
		return true;
	}

	@Range(min = 3, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "plaqueSeconds",
		name = "Plaque time",
		description = "How long the plaque stays up",
		position = 2,
		section = finds
	)
	default int plaqueSeconds()
	{
		return 8;
	}

	@ConfigItem(
		keyName = "chatLine",
		name = "Luck in chat",
		description = "Add a line to the chat box saying how lucky each new slot was",
		position = 3,
		section = finds
	)
	default boolean chatLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rates",
		name = "Rates",
		description = "Typical kills per hour for a normal account or an ironman",
		position = 1,
		section = estimates
	)
	default Rates rates()
	{
		return Rates.AUTO;
	}

	@ConfigItem(
		keyName = "learnPace",
		name = "Learn my pace",
		description = "Time your kill counts and use your own pace once Log Insight has seen enough of them",
		position = 2,
		section = estimates
	)
	default boolean learnPace()
	{
		return true;
	}
}

package com.codex.loginsight;

import com.codex.loginsight.core.Analyst;
import com.codex.loginsight.core.Announcements;
import com.codex.loginsight.core.ChatReader;
import com.codex.loginsight.core.LogStructure;
import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Progress;
import com.codex.loginsight.core.Report;
import com.codex.loginsight.core.Unlocks;
import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import com.codex.loginsight.overlay.FindPlaque;
import com.codex.loginsight.ui.Format;
import com.codex.loginsight.ui.ItemIcons;
import com.codex.loginsight.ui.LogInsightPanel;
import com.codex.loginsight.ui.Sigil;
import com.codex.loginsight.ui.Theme;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.awt.Color;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.StructComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Codex Log Insight",
	description = "Collection log analytics: your luck at your kill counts, time left on each page and the fastest slots to chase",
	tags = {"collection", "log", "clog", "luck", "dry", "drop", "rate", "pet", "codex"}
)
public class CodexLogInsightPlugin extends Plugin
{
	private static final String PROGRESS_KEY = "progress";
	/** The script that sends the client every owned slot when the log's Search is opened. */
	private static final int COLLECTION_TRANSMIT = 4100;
	/** Enum of the log's tabs; each tab struct points to its pages, each page to its slots. */
	private static final int TAB_ENUM = 2102;
	private static final int TAB_PAGES_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_PARAM = 690;
	/** Slots whose id the log swaps for a stand-in, mapping the stand-in back. */
	private static final int REPLACEMENT_ENUM = 3721;
	private static final String[] TAB_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};
	private static final int TRANSMIT_SETTLE_TICKS = 3;
	private static final int SAVE_TICKS = 100;
	private static final int ANALYSE_GAP_TICKS = 2;
	private static final String POPUP_PREFIX = "New item:";
	/** Skill levels and quests are read again this often, to notice what has opened up. */
	private static final int UNLOCKS_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexLogInsightConfig config;

	private final FindPlaque plaque = new FindPlaque();
	private final AtomicInteger generation = new AtomicInteger();
	private final Set<Integer> harvest = new HashSet<>();
	private final Map<Integer, Integer> replacements = new HashMap<>();

	private LogData data;
	private Analyst analyst;
	private ChatReader chat;
	private LogInsightPanel panel;
	private NavigationButton navButton;

	private LogStructure structure = LogStructure.empty();
	private Progress progress;
	private String profile;
	private boolean dirty;
	private boolean unsaved;
	private int ticksSinceSave;
	private int ticksSinceAnalysis;
	private int lastTransmitTick = -1;
	private int officialOwned = -1;
	private int officialTotal = -1;
	private final Map<String, Quest> questsNeeded = new HashMap<>();
	private Unlocks unlocks = Unlocks.UNKNOWN;
	private int unlocksReadAt = -1;
	private boolean notificationStarted;
	/** The chat line and the pop-up can both announce one slot; the second is ignored. */
	private final Announcements announcements = new Announcements();

	@Provides
	CodexLogInsightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexLogInsightConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		data = LogData.load(gson);
		analyst = new Analyst(data);
		chat = new ChatReader(data.getLabels());
		Map<String, Quest> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			quests.putIfAbsent(Unlocks.normalise(quest.name()), quest);
			quests.putIfAbsent(Unlocks.normalise(quest.getName()), quest);
		}
		for (String name : data.questsNeeded())
		{
			Quest quest = quests.get(Unlocks.normalise(name));
			if (quest != null)
			{
				questsNeeded.put(name, quest);
			}
		}
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new LogInsightPanel(icons);
		navButton = NavigationButton.builder()
			.tooltip("Codex Log Insight")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadProgress();
				buildStructure();
				dirty = true;
			}
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			save();
			progress = null;
			profile = null;
		});
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		plaque.clear();
		generation.incrementAndGet();
		structure = LogStructure.empty();
		harvest.clear();
		lastTransmitTick = -1;
		panel = null;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// ConfigManager writes its changes to disk in this same event, before a save queued on the
		// client thread runs, so a save made here has to be sent on by hand or it is never written.
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invokeLater(() ->
		{
			try
			{
				if (save())
				{
					configManager.sendConfig();
				}
			}
			finally
			{
				done.complete(null);
			}
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			harvest.clear();
			lastTransmitTick = -1;
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			save();
			progress = null;
			profile = null;
			officialOwned = -1;
			officialTotal = -1;
			unlocks = Unlocks.UNKNOWN;
			unlocksReadAt = -1;
			announcements.clear();
			plaque.clear();
			publish(Report.loggedOut(), null);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		progress = null;
		loadProgress();
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexLogInsightConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.showPlaque())
		{
			plaque.clear();
		}
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (progress == null)
		{
			loadProgress();
			dirty |= progress != null;
		}
		if (structure.isEmpty())
		{
			buildStructure();
			dirty |= !structure.isEmpty();
		}
		if (lastTransmitTick >= 0 && client.getTickCount() - lastTransmitTick > TRANSMIT_SETTLE_TICKS)
		{
			finishFullRead();
		}

		int owned = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total > 0 && (owned != officialOwned || total != officialTotal))
		{
			officialOwned = owned;
			officialTotal = total;
			dirty = true;
		}

		if (progress != null && (unlocksReadAt < 0 || client.getTickCount() - unlocksReadAt >= UNLOCKS_TICKS))
		{
			readUnlocks();
		}

		ticksSinceAnalysis++;
		if (dirty && ticksSinceAnalysis >= ANALYSE_GAP_TICKS)
		{
			dirty = false;
			ticksSinceAnalysis = 0;
			analyse();
		}
		if (unsaved && ++ticksSinceSave >= SAVE_TICKS)
		{
			save();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.NOTIFICATION_START)
		{
			notificationStarted = true;
			return;
		}
		if (event.getScriptId() == ScriptID.NOTIFICATION_DELAY)
		{
			readNotification();
			return;
		}
		if (event.getScriptId() != COLLECTION_TRANSMIT || progress == null || isAnotherPlayersLog())
		{
			return;
		}
		ScriptEvent script = event.getScriptEvent();
		Object[] args = script == null ? null : script.getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = (Integer) args[2];
		if (itemId > 0 && quantity > 0)
		{
			harvest.add(replacements.getOrDefault(itemId, itemId));
			lastTransmitTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			// The page's header and slots are filled in after the script returns.
			clientThread.invokeLater(this::readOpenPage);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (progress == null || type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		String message = event.getMessage();
		ChatReader.Count count = chat.count(message);
		if (count != null && count.value >= 0)
		{
			progress.setCounter(count.label, count.value);
			if (config.learnPace())
			{
				progress.paceFor(count.label).record(count.value, System.currentTimeMillis());
			}
			changed();
			return;
		}
		String slot = ChatReader.newSlot(message);
		if (slot != null)
		{
			announced(slot, Announcements.Channel.CHAT);
		}
	}

	/** The game's pop-up for a new slot, for players who turned the chat line off. */
	private void readNotification()
	{
		if (!notificationStarted)
		{
			return;
		}
		notificationStarted = false;
		String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
		if (progress == null || title == null || body == null || !"Collection log".equalsIgnoreCase(title.trim()))
		{
			return;
		}
		String text = Text.removeTags(body).trim();
		if (text.startsWith(POPUP_PREFIX))
		{
			announced(text.substring(POPUP_PREFIX.length()).trim(), Announcements.Channel.POPUP);
		}
	}

	private void announced(String slot, Announcements.Channel channel)
	{
		if (!announcements.fresh(slot, channel, System.currentTimeMillis()))
		{
			return;
		}
		onNewSlot(slot.trim());
	}

	/** Reads the account's real skill levels and which needed quests are still unfinished. */
	private void readUnlocks()
	{
		unlocksReadAt = client.getTickCount();
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			levels.put(skill.name(), client.getRealSkillLevel(skill));
		}
		Set<String> unfinished = new HashSet<>();
		for (Map.Entry<String, Quest> quest : questsNeeded.entrySet())
		{
			if (quest.getValue().getState(client) != QuestState.FINISHED)
			{
				unfinished.add(quest.getKey());
			}
		}
		Unlocks read = new Unlocks(levels, unfinished);
		if (!read.equals(unlocks))
		{
			unlocks = read;
			dirty = true;
		}
	}

	/** Reads the page open in the collection log: its counters and which slots are owned. */
	private void readOpenPage()
	{
		if (progress == null || isAnotherPlayersLog())
		{
			return;
		}
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget[] lines = header == null ? null : header.getDynamicChildren();
		if (lines == null || lines.length == 0 || lines[0] == null)
		{
			return;
		}
		String page = Text.removeTags(lines[0].getText()).trim();
		if (page.isEmpty())
		{
			return;
		}
		List<String> labels = new ArrayList<>();
		for (int i = 1; i < lines.length; i++)
		{
			ChatReader.Count counter = lines[i] == null ? null : ChatReader.pageCounter(lines[i].getText());
			if (counter != null)
			{
				labels.add(counter.label);
				progress.setCounter(counter.label, counter.value);
			}
		}
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS);
		Widget[] slots = items == null ? null : items.getDynamicChildren();
		if (slots != null)
		{
			for (Widget slot : slots)
			{
				// The log draws owned slots solid and missing ones faded.
				if (slot != null && slot.getItemId() > 0 && slot.getOpacity() == 0)
				{
					progress.addOwned(replacements.getOrDefault(slot.getItemId(), slot.getItemId()));
				}
			}
		}
		progress.setPageLabels(page, labels);
		progress.markPageRead(page, System.currentTimeMillis());
		changed();
	}

	private void finishFullRead()
	{
		lastTransmitTick = -1;
		if (progress == null || harvest.isEmpty())
		{
			harvest.clear();
			return;
		}
		for (int id : harvest)
		{
			progress.addOwned(id);
		}
		harvest.clear();
		progress.setFullReadAt(System.currentTimeMillis());
		changed();
		save();
	}

	private void onNewSlot(String name)
	{
		List<Integer> ids = structure.idsNamed(name);
		int itemId = -1;
		for (int id : ids)
		{
			if (!progress.owns(id))
			{
				itemId = id;
				break;
			}
		}
		if (itemId < 0 && !ids.isEmpty())
		{
			itemId = ids.get(0);
		}

		ItemOdds odds = itemId > 0 ? data.odds(itemId) : null;
		String label = null;
		int count = 0;
		double chance = 0;
		double luckier = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			Integer value = progress.counter(label);
			count = value == null ? 0 : value;
			chance = odds.mainChance();
			luckier = odds.dryChance(progress.getCounters());
		}
		else if (itemId > 0)
		{
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				chance = Math.max(chance, 1 / Math.max(1, drop.getAttempts()));
			}
		}
		List<LogStructure.Page> pages = itemId > 0 ? structure.pagesOf(itemId) : java.util.Collections.emptyList();
		String page = pages.isEmpty() ? null : pages.get(0).getName();
		if (itemId > 0)
		{
			progress.addOwned(itemId);
		}
		progress.addFind(new Progress.Find(itemId, name, page, label, count, chance, luckier, System.currentTimeMillis()));
		changed();
		save();

		String odd = chance > 0 ? Format.chance(chance) + (count > 0 ? " at " + Format.count(count) + " " + Format.counterName(label) + " kc" : "") : page;
		String verdict = luckier >= 0 ? "Luckier than " + Math.round(luckier * 100) + "% of players" : null;
		Color color = luckier >= 0 ? Theme.luck(Luck.verdict(luckier)) : Theme.GOLD;
		if (config.showPlaque())
		{
			plaque.show(new FindPlaque.View(name, page, odd, verdict, color, itemId > 0 && data.isPet(itemId),
				itemId > 0 ? itemManager.getImage(itemId) : null, System.currentTimeMillis(), config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine() && (chance > 0 || verdict != null))
		{
			ChatMessageBuilder line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Log Insight: ")
				.append(ChatColorType.NORMAL).append(name);
			if (odd != null)
			{
				line.append(", " + odd);
			}
			if (verdict != null)
			{
				line.append(". ").append(ChatColorType.HIGHLIGHT).append(verdict).append(ChatColorType.NORMAL);
			}
			line.append(".");
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line.build())
				.build());
		}
	}

	private void changed()
	{
		dirty = true;
		unsaved = true;
	}

	private boolean isAnotherPlayersLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private boolean ironRates()
	{
		switch (config.rates())
		{
			case IRON:
				return true;
			case MAIN:
				return false;
			default:
				return client.getVarbitValue(VarbitID.IRONMAN) != 0;
		}
	}

	/** Reads the log's tabs, pages and slots from the game cache. */
	private void buildStructure()
	{
		EnumComposition tabEnum = client.getEnum(TAB_ENUM);
		int[] tabStructs = tabEnum == null ? null : tabEnum.getIntVals();
		if (tabStructs == null || tabStructs.length == 0)
		{
			return;
		}
		replacements.clear();
		EnumComposition swap = client.getEnum(REPLACEMENT_ENUM);
		if (swap != null)
		{
			int[] keys = swap.getKeys();
			int[] values = swap.getIntVals();
			for (int i = 0; i < Math.min(keys.length, values.length); i++)
			{
				replacements.put(keys[i], values[i]);
			}
		}

		List<LogStructure.Tab> tabs = new ArrayList<>();
		Map<Integer, String> names = new HashMap<>();
		for (int t = 0; t < tabStructs.length; t++)
		{
			StructComposition tabStruct = client.getStructComposition(tabStructs[t]);
			EnumComposition pageEnum = tabStruct == null ? null : client.getEnum(tabStruct.getIntValue(TAB_PAGES_PARAM));
			if (pageEnum == null)
			{
				continue;
			}
			String tabName = t < TAB_NAMES.length ? TAB_NAMES[t] : "Tab " + (t + 1);
			List<LogStructure.Page> pages = new ArrayList<>();
			for (int pageStructId : pageEnum.getIntVals())
			{
				StructComposition pageStruct = client.getStructComposition(pageStructId);
				EnumComposition itemEnum = pageStruct == null ? null : client.getEnum(pageStruct.getIntValue(PAGE_ITEMS_PARAM));
				if (itemEnum == null)
				{
					continue;
				}
				List<Integer> items = new ArrayList<>();
				for (int raw : itemEnum.getIntVals())
				{
					int id = replacements.getOrDefault(raw, raw);
					items.add(id);
					names.computeIfAbsent(id, k -> Text.removeTags(itemManager.getItemComposition(k).getName()));
				}
				pages.add(new LogStructure.Page(tabName, pageStruct.getStringValue(PAGE_NAME_PARAM), items));
			}
			tabs.add(new LogStructure.Tab(tabName, pages));
		}
		structure = new LogStructure(tabs, names);
		log.debug("Collection log read: {} tabs, {} slots", tabs.size(), structure.getUniqueSlots());
	}

	private void loadProgress()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		profile = key;
		Progress loaded = null;
		String json = configManager.getRSProfileConfiguration(CodexLogInsightConfig.GROUP, PROGRESS_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				loaded = gson.fromJson(json, Progress.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Could not read saved collection log progress, starting fresh", e);
			}
		}
		progress = loaded == null ? new Progress() : loaded;
		seedFromChatCommands();
	}

	/**
	 * Brings counters up to the kill counts RuneLite's chat commands remember, which can be
	 * newer than the last time a log page was opened. Counts only ever go up.
	 */
	private void seedFromChatCommands()
	{
		for (String label : data.getLabels())
		{
			Integer known = progress.counter(label);
			for (String key : ChatReader.savedKeys(label))
			{
				Integer count = configManager.getRSProfileConfiguration("killcount", key, Integer.class);
				if (count != null && count > 0)
				{
					if (known == null || count > known)
					{
						progress.setCounter(label, count);
					}
					break;
				}
			}
		}
	}

	/** Writes progress to the profile if it changed, and says whether it did. */
	private boolean save()
	{
		ticksSinceSave = 0;
		if (progress == null || profile == null || !unsaved)
		{
			return false;
		}
		unsaved = false;
		configManager.setConfiguration(CodexLogInsightConfig.GROUP, profile, PROGRESS_KEY, gson.toJson(progress));
		return true;
	}

	private void analyse()
	{
		if (progress == null)
		{
			publish(Report.loggedOut(), null);
			return;
		}
		Progress snapshot = progress.copy();
		LogStructure shape = structure;
		boolean iron = ironRates();
		boolean pace = config.learnPace();
		Unlocks can = unlocks;
		int owned = officialOwned;
		int total = officialTotal;
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		int ticket = generation.incrementAndGet();
		executor.execute(() ->
		{
			try
			{
				Report report = analyst.analyse(shape, snapshot, iron, pace, owned, total, can);
				if (ticket == generation.get())
				{
					publish(report, name);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Log Insight analysis failed", e);
			}
		});
	}

	private void publish(Report report, String name)
	{
		LogInsightPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(report, name));
		}
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Turns the log's shape, the bundled rates and this account's progress into a Report.
 * Pure Java over immutable inputs, so it runs off the client thread and is tested
 * without a game.
 */
public final class Analyst
{
	/** Kill count gaps needed before your own pace replaces the typical rate. */
	static final int PACE_SAMPLES = 15;
	private static final int DRIEST = 6;
	/** At most this many of the driest slots come from one page, so one dry casket tier cannot fill the list. */
	private static final int DRIEST_PER_PAGE = 2;
	private static final double DRY_SHOWN_BELOW = 0.35;

	private final LogData data;
	/** The counter each activity advances, when its slots agree on one. */
	private final Map<Integer, String> activityLabels = new HashMap<>();
	private static final int MAX_CACHED = 20_000;
	private final Map<String, Eval> evaluations = new java.util.concurrent.ConcurrentHashMap<>();

	public Analyst(LogData data)
	{
		this.data = data;
		for (Activity activity : data.getActivities())
		{
			Map<String, Integer> votes = new HashMap<>();
			for (Activity.Drop drop : activity.getDrops())
			{
				ItemOdds odds = data.odds(drop.getItemId());
				if (odds != null)
				{
					votes.merge(odds.mainLabel(), 1, Integer::sum);
				}
			}
			votes.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.filter(e -> e.getValue() * 2 >= activity.getDrops().size())
				.ifPresent(e -> activityLabels.put(activity.getIndex(), e.getKey()));
		}
	}

	/**
	 * @param ownPace use the pace learned from your kill counts where there is enough of it
	 */
	public Report analyse(LogStructure structure, Progress progress, boolean iron, boolean ownPace, int officialOwned,
		int officialTotal)
	{
		return analyse(structure, progress, iron, ownPace, officialOwned, officialTotal, Unlocks.UNKNOWN);
	}

	/**
	 * @param unlocks what the account can do yet; activities it cannot do sink below the rest
	 */
	public Report analyse(LogStructure structure, Progress progress, boolean iron, boolean ownPace, int officialOwned,
		int officialTotal, Unlocks unlocks)
	{
		Rates rates = new Rates(progress, iron, ownPace);
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();

		List<Report.PageReport> pages = new ArrayList<>();
		Set<Integer> unique = new LinkedHashSet<>();
		int complete = 0;
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				Report.PageReport report = page(structure, page, progress, rates);
				pages.add(report);
				if (report.isComplete())
				{
					complete++;
				}
				unique.addAll(page.getItems());
			}
		}

		int knownOwned = 0;
		List<Integer> missing = new ArrayList<>();
		for (int id : unique)
		{
			if (owned.contains(id))
			{
				knownOwned++;
			}
			else
			{
				missing.add(id);
			}
		}

		Finish finish = finish(missing, owned, rates);
		Luck luck = luck(unique, owned, counters);
		List<Report.ItemReport> driest = driest(structure, missing, progress, rates);
		List<Report.Hunt> hunts = hunts(structure, owned, rates, unlocks);

		return new Report(true, !structure.isEmpty(), officialOwned, officialTotal, knownOwned, unique.size(),
			progress.getFullReadAt(), progress.pagesReadCount(), pages.size(), complete, luck, finish.hours,
			finish.unrated, iron, pages, hunts, driest, progress.getFinds());
	}

	/** Builds the report for one slot, for the panel and for the drop plaque. */
	public Report.ItemReport item(LogStructure structure, int itemId, String page, Progress progress, boolean iron)
	{
		return item(structure, itemId, page, progress, new Rates(progress, iron, true));
	}

	private Report.PageReport page(LogStructure structure, LogStructure.Page page, Progress progress, Rates rates)
	{
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();
		List<Report.ItemReport> items = new ArrayList<>();
		List<Integer> missing = new ArrayList<>();
		Map<String, Integer> labelVotes = new LinkedHashMap<>();
		int ownedCount = 0;
		for (int id : page.getItems())
		{
			items.add(item(structure, id, page.getName(), progress, rates));
			if (owned.contains(id))
			{
				ownedCount++;
			}
			else
			{
				missing.add(id);
			}
			ItemOdds odds = data.odds(id);
			if (odds != null)
			{
				for (ItemOdds.Roll roll : odds.getRolls())
				{
					labelVotes.merge(roll.getLabel(), roll.getLabel().equals(odds.mainLabel()) ? 2 : 1, Integer::sum);
				}
			}
		}

		String mainLabel = labelVotes.entrySet().stream()
			.max(Map.Entry.comparingByValue())
			.map(Map.Entry::getKey)
			.orElse(null);
		List<String> shownLabels = progress.pageLabels(page.getName());
		if (shownLabels == null)
		{
			shownLabels = new ArrayList<>(labelVotes.keySet());
		}
		List<String> lines = new ArrayList<>();
		for (String label : shownLabels)
		{
			Integer value = counters.get(label);
			if (value != null)
			{
				lines.add(label + ": " + String.format("%,d", value));
			}
		}
		if (mainLabel == null && !shownLabels.isEmpty())
		{
			mainLabel = shownLabels.get(0);
		}
		Integer count = mainLabel == null ? null : counters.get(mainLabel);

		Finish finish = finish(missing, owned, rates);
		Next next = next(missing, owned, rates);
		Luck luck = luck(page.getItems(), owned, counters);
		return new Report.PageReport(page.getTab(), page.getName(), ownedCount, page.getItems().size(), lines,
			count == null ? -1 : count, mainLabel, luck, finish.hours, next.hours, next.source, finish.unrated,
			progress.isPageRead(page.getName()), items);
	}

	private Report.ItemReport item(LogStructure structure, int id, String page, Progress progress, Rates rates)
	{
		ItemOdds odds = data.odds(id);
		double chance = 0;
		String label = null;
		int count = -1;
		double dry = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			chance = odds.mainChance();
			Integer value = progress.counter(label);
			count = value == null ? -1 : value;
			dry = odds.dryChance(progress.getCounters());
		}
		Activity.Drop fastest = rates.fastest(id);
		String source = null;
		double hours = Double.POSITIVE_INFINITY;
		if (fastest != null)
		{
			Activity activity = data.activity(fastest.getActivityIndex());
			source = activity.getName();
			hours = rates.hours(activity, fastest.getAttempts());
			if (chance == 0)
			{
				chance = 1 / fastest.getAttempts();
			}
		}
		return new Report.ItemReport(id, structure.name(id), page, progress.owns(id), data.isPet(id), chance, label,
			count, dry, source, hours);
	}

	private Luck luck(Collection<Integer> items, Set<Integer> owned, Map<String, Integer> counters)
	{
		List<Double> chances = new ArrayList<>();
		int have = 0;
		Set<Integer> seen = new HashSet<>();
		for (int id : items)
		{
			if (!seen.add(id))
			{
				continue;
			}
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double dry = odds.dryChance(counters);
			if (dry < 0)
			{
				continue;
			}
			chances.add(1 - dry);
			if (owned.contains(id))
			{
				have++;
			}
		}
		if (chances.isEmpty())
		{
			return null;
		}
		double[] array = new double[chances.size()];
		for (int i = 0; i < array.length; i++)
		{
			array[i] = chances.get(i);
		}
		return Luck.of(array, have);
	}

	private List<Report.ItemReport> driest(LogStructure structure, List<Integer> missing, Progress progress, Rates rates)
	{
		List<Report.ItemReport> dry = new ArrayList<>();
		for (int id : missing)
		{
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double chance = odds.dryChance(progress.getCounters());
			if (chance >= 0 && chance < DRY_SHOWN_BELOW)
			{
				List<LogStructure.Page> pages = structure.pagesOf(id);
				dry.add(item(structure, id, pages.isEmpty() ? null : pages.get(0).getName(), progress, rates));
			}
		}
		dry.sort(Comparator.comparingDouble(Report.ItemReport::getDryChance));
		List<Report.ItemReport> shown = new ArrayList<>();
		Map<String, Integer> perPage = new HashMap<>();
		for (Report.ItemReport item : dry)
		{
			if (perPage.merge(String.valueOf(item.getPage()), 1, Integer::sum) <= DRIEST_PER_PAGE)
			{
				shown.add(item);
			}
			if (shown.size() == DRIEST)
			{
				break;
			}
		}
		return shown;
	}

	private List<Report.Hunt> hunts(LogStructure structure, Set<Integer> owned, Rates rates, Unlocks unlocks)
	{
		Set<Integer> inLog = new HashSet<>();
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				inLog.addAll(page.getItems());
			}
		}
		List<Report.Hunt> hunts = new ArrayList<>();
		for (Activity activity : data.getActivities())
		{
			double perHour = rates.perHour(activity);
			if (perHour <= 0)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, id -> inLog.isEmpty() || inLog.contains(id));
			if (eval.remaining == 0 || Double.isInfinite(eval.nextAttempts))
			{
				continue;
			}
			boolean pet = false;
			for (int id : eval.missing)
			{
				pet |= data.isPet(id);
			}
			double petHours = Double.POSITIVE_INFINITY;
			int petItem = -1;
			if (pet)
			{
				Eval pets = evaluate(activity, owned, id -> data.isPet(id) && (inLog.isEmpty() || inLog.contains(id)));
				petHours = rates.hoursFor(activity, pets.nextAttempts);
				petItem = pets.nextItem;
			}
			hunts.add(new Report.Hunt(activity.getName(), activity.getCategory(),
				rates.hoursFor(activity, eval.nextAttempts), rates.hoursFor(activity, eval.allAttempts), eval.remaining,
				eval.nextItem, eval.nextItem < 0 ? null : structure.name(eval.nextItem), eval.nextChance, eval.nextExact, perHour,
				rates.isOwnPace(activity), pet, eval.missing, petHours, petItem, petItem < 0 ? null : structure.name(petItem),
				unlocks.missing(activity)));
		}
		// What can be done now comes first, each part ranked by the wait for a new slot.
		hunts.sort(Comparator.comparing((Report.Hunt h) -> h.getLockedBy() != null)
			.thenComparingDouble(Report.Hunt::getHoursToNext));
		return hunts;
	}

	/** Hours to finish these slots, each hunted at its fastest source. */
	private Finish finish(List<Integer> missing, Set<Integer> owned, Rates rates)
	{
		Map<Integer, Set<Integer>> byActivity = new LinkedHashMap<>();
		int unrated = 0;
		for (int id : missing)
		{
			Activity.Drop fastest = rates.fastest(id);
			if (fastest == null)
			{
				unrated++;
				continue;
			}
			byActivity.computeIfAbsent(fastest.getActivityIndex(), k -> new HashSet<>()).add(id);
		}
		double hours = 0;
		for (Map.Entry<Integer, Set<Integer>> e : byActivity.entrySet())
		{
			Activity activity = data.activity(e.getKey());
			Eval eval = evaluate(activity, owned, e.getValue()::contains);
			hours += rates.hoursFor(activity, eval.allAttempts);
		}
		return new Finish(byActivity.isEmpty() ? (unrated > 0 ? Double.POSITIVE_INFINITY : 0) : hours, unrated);
	}

	/** The soonest new slot among these, from any activity that drops one. */
	private Next next(List<Integer> missing, Set<Integer> owned, Rates rates)
	{
		Set<Integer> wanted = new HashSet<>(missing);
		Set<Integer> activities = new LinkedHashSet<>();
		for (int id : missing)
		{
			for (Activity.Drop drop : data.dropsOf(id))
			{
				activities.add(drop.getActivityIndex());
			}
		}
		double best = Double.POSITIVE_INFINITY;
		String source = null;
		for (int index : activities)
		{
			Activity activity = data.activity(index);
			if (rates.perHour(activity) <= 0)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, wanted::contains);
			double hours = rates.hoursFor(activity, eval.nextAttempts);
			if (hours < best)
			{
				best = hours;
				source = activity.getName();
			}
		}
		return new Next(best, source);
	}

	/**
	 * Walks an activity's table in order. A slot can roll when it is missing and, if it
	 * only drops after the slot before it, that slot is owned. Slots earned outright are
	 * paid for one by one, so their counts add up; rolled slots wait side by side, and a
	 * run of rolled slots that only drop in order waits one piece after another.
	 */
	private Eval evaluate(Activity activity, Set<Integer> owned, java.util.function.IntPredicate include)
	{
		// The result depends only on which slots are wanted and which are owned, so it is kept between
		// reports: a new kill count costs nothing here, only a new slot does.
		StringBuilder key = new StringBuilder().append(activity.getIndex());
		boolean previousOwned = false;
		for (Activity.Drop drop : activity.getDrops())
		{
			int id = drop.getItemId();
			boolean has = owned.contains(id);
			if (!has && include.test(id))
			{
				key.append(drop.isSequential() && previousOwned ? ',' : ';').append(id);
			}
			previousOwned = has;
		}
		String cacheKey = key.toString();
		Eval cached = evaluations.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}
		Eval eval = compute(activity, owned, include);
		if (evaluations.size() > MAX_CACHED)
		{
			evaluations.clear();
		}
		evaluations.put(cacheKey, eval);
		return eval;
	}

	private Eval compute(Activity activity, Set<Integer> owned, java.util.function.IntPredicate include)
	{
		Eval eval = new Eval();
		double chanceSum = 0;
		double exactNext = Double.POSITIVE_INFINITY;
		int exactItem = -1;
		double bestChance = 0;
		double fixed = 0;
		List<double[]> runs = new ArrayList<>();
		boolean previousOwned = false;
		boolean previousRolledOpen = false;
		for (Activity.Drop drop : activity.getDrops())
		{
			int id = drop.getItemId();
			boolean has = owned.contains(id);
			boolean rolledOpen = false;
			if (!has && include.test(id))
			{
				eval.missing.add(id);
				boolean canRoll = !drop.isSequential() || previousOwned;
				double attempts = Math.max(1, drop.getAttempts());
				if (drop.isExact())
				{
					fixed += attempts;
					if (canRoll && attempts < exactNext)
					{
						exactNext = attempts;
						exactItem = id;
					}
				}
				else
				{
					if (canRoll)
					{
						double chance = 1 / attempts;
						chanceSum += chance;
						if (chance > bestChance)
						{
							bestChance = chance;
							eval.nextItem = id;
						}
					}
					if (drop.isSequential() && previousRolledOpen && !runs.isEmpty())
					{
						double[] run = runs.get(runs.size() - 1);
						run[0] += attempts;
						run[1]++;
					}
					else
					{
						runs.add(new double[]{attempts, 1});
					}
					rolledOpen = true;
				}
			}
			previousRolledOpen = rolledOpen;
			previousOwned = has;
		}
		if (exactItem >= 0 && (eval.nextItem < 0 || exactNext < 1 / chanceSum))
		{
			eval.nextItem = exactItem;
			eval.nextExact = true;
			bestChance = 1 / exactNext;
		}
		double[] means = new double[runs.size()];
		int[] stages = new int[runs.size()];
		for (int i = 0; i < means.length; i++)
		{
			means[i] = runs.get(i)[0];
			stages[i] = (int) runs.get(i)[1];
		}
		eval.remaining = eval.missing.size();
		eval.nextChance = bestChance;
		eval.nextAttempts = eval.remaining == 0 ? Double.POSITIVE_INFINITY : Odds.attemptsToNext(chanceSum, exactNext);
		double all = Odds.attemptsToAll(fixed, means, stages);
		eval.allAttempts = eval.remaining == 0 ? 0
			: Double.isFinite(eval.nextAttempts) ? Math.max(eval.nextAttempts, all) : all;
		return eval;
	}

	/** Completions per hour for each activity: your own pace where it is known, the typical rate otherwise. */
	private final class Rates
	{
		private final Progress progress;
		private final boolean iron;
		private final boolean ownPace;
		private final Map<Integer, Activity.Drop> fastest = new HashMap<>();

		Rates(Progress progress, boolean iron, boolean ownPace)
		{
			this.progress = progress;
			this.iron = iron;
			this.ownPace = ownPace;
		}

		boolean isOwnPace(Activity activity)
		{
			if (!ownPace)
			{
				return false;
			}
			String label = activityLabels.get(activity.getIndex());
			Progress.Pace pace = label == null ? null : progress.pace(label);
			return pace != null && pace.getSamples() >= PACE_SAMPLES && pace.perHour() > 0;
		}

		double perHour(Activity activity)
		{
			if (isOwnPace(activity))
			{
				return progress.pace(activityLabels.get(activity.getIndex())).perHour();
			}
			return activity.perHour(iron);
		}

		double hours(Activity activity, double attempts)
		{
			return hoursFor(activity, attempts);
		}

		double hoursFor(Activity activity, double attempts)
		{
			double perHour = perHour(activity);
			if (perHour <= 0 || Double.isInfinite(attempts))
			{
				return Double.POSITIVE_INFINITY;
			}
			return attempts / perHour + activity.getSetupHours();
		}

		/** The source that gives this slot soonest on its own, or null. */
		Activity.Drop fastest(int itemId)
		{
			if (fastest.containsKey(itemId))
			{
				return fastest.get(itemId);
			}
			Activity.Drop best = null;
			double bestHours = Double.POSITIVE_INFINITY;
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				double hours = hoursFor(data.activity(drop.getActivityIndex()), drop.getAttempts());
				if (hours < bestHours)
				{
					bestHours = hours;
					best = drop;
				}
			}
			fastest.put(itemId, best);
			return best;
		}
	}

	private static final class Eval
	{
		final List<Integer> missing = new ArrayList<>();
		int remaining;
		int nextItem = -1;
		/** The next slot is earned after a fixed number of attempts rather than rolled. */
		boolean nextExact;
		double nextChance;
		double nextAttempts;
		double allAttempts;
	}

	private static final class Finish
	{
		final double hours;
		final int unrated;

		Finish(double hours, int unrated)
		{
			this.hours = hours;
			this.unrated = unrated;
		}
	}

	private static final class Next
	{
		final double hours;
		final String source;

		Next(double hours, String source)
		{
			this.hours = hours;
			this.source = source;
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import java.util.Locale;

/**
 * The game can announce one new slot twice: once in chat and once in the pop-up. Several
 * slots from one casket arrive in chat together, while their pop-ups queue and show one
 * after another, so each announcement is matched against an unclaimed one of the same
 * slot from the other channel rather than only the last one seen.
 */
public final class Announcements
{
	public enum Channel
	{
		CHAT,
		POPUP
	}

	/** Pop-ups queue behind each other, so their partner can be a while behind. */
	static final long WINDOW_MS = 120_000;

	private final Deque<Entry> recent = new ArrayDeque<>();

	/** @return true when this slot has not already been announced by the other channel */
	public boolean fresh(String slot, Channel channel, long now)
	{
		if (slot == null || slot.trim().isEmpty())
		{
			return false;
		}
		while (!recent.isEmpty() && now - recent.peekFirst().at > WINDOW_MS)
		{
			recent.removeFirst();
		}
		String key = slot.trim().toLowerCase(Locale.ENGLISH);
		for (Iterator<Entry> it = recent.iterator(); it.hasNext(); )
		{
			Entry entry = it.next();
			if (entry.channel != channel && entry.slot.equals(key))
			{
				it.remove();
				return false;
			}
		}
		recent.addLast(new Entry(key, channel, now));
		return true;
	}

	public void clear()
	{
		recent.clear();
	}

	private static final class Entry
	{
		final String slot;
		final Channel channel;
		final long at;

		Entry(String slot, Channel channel, long at)
		{
			this.slot = slot;
			this.channel = channel;
			this.at = at;
		}
	}
}

package com.codex.loginsight.core;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/** Reads the game messages that move the collection log: new slots and kill counts. */
public final class ChatReader
{
	private static final Pattern NEW_SLOT = Pattern.compile("New item added to your collection log: (.+)");
	// The same shape RuneLite's chat commands read, so every boss, raid and minigame count is caught.
	private static final Pattern COUNT = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?<name>.+?) (?<post>(?:(?:kill|harvest|lap|completion|success|chest|opened) )?(?:count )?)is: ?(?<count>[0-9,]+)");
	private static final Pattern CLUES = Pattern.compile("You have completed (?<count>[0-9,]+) (?<tier>beginner|easy|medium|hard|elite|master) Treasure Trails?", Pattern.CASE_INSENSITIVE);
	private static final Pattern COFFINS = Pattern.compile("You have opened the Grand Hallowed Coffin (?<count>[0-9,]+) times?!");
	private static final Pattern RIFTS = Pattern.compile("Amount of Rifts you have closed: (?<count>[0-9,]+)\\.", Pattern.CASE_INSENSITIVE);
	private static final Pattern RUMOURS = Pattern.compile("You have completed (?<count>[0-9,]+) rumours? for the Hunter Guild\\.");
	private static final Pattern SUFFIX = Pattern.compile(" (kills|completions|completion count|opened|chests opened|kill count|count)$", Pattern.CASE_INSENSITIVE);

	/** Chat names that differ from the counter the collection log shows. */
	private static final Map<String, String> ALIASES = new HashMap<>();

	static
	{
		ALIASES.put("barrows", "Barrows Chests opened");
		ALIASES.put("barrows chest", "Barrows Chests opened");
		ALIASES.put("barrows chests", "Barrows Chests opened");
		ALIASES.put("lunar chest", "Lunar Chests opened");
		ALIASES.put("lunar chests", "Lunar Chests opened");
		ALIASES.put("gauntlet", "Gauntlet completion count");
		ALIASES.put("corrupted gauntlet", "Corrupted Gauntlet completion count");
		ALIASES.put("theatre of blood: hard mode", "Theatre of Blood (Hard) completions");
		ALIASES.put("theatre of blood: entry mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("theatre of blood: story mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("tombs of amascut: expert mode", "Tombs of Amascut (Expert) completions");
		ALIASES.put("tombs of amascut: entry mode", "Tombs of Amascut (Entry) completions");
		ALIASES.put("chambers of xeric challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("chambers of xeric: challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("the leviathan", "Leviathan kills");
		ALIASES.put("the whisperer", "Whisperer kills");
		ALIASES.put("the nightmare", "Nightmare kills");
		ALIASES.put("the hueycoatl", "Hueycoatl kills");
		ALIASES.put("tztok-jad", "TzTok-Jad kills");
		ALIASES.put("tzkal-zuk", "TzKal-Zuk kills");
		ALIASES.put("wintertodt", "Wintertodt kills");
		ALIASES.put("hespori", "Hespori kills");
		ALIASES.put("grotesque guardians", "Grotesque Guardian kills");
		ALIASES.put("royal titans", "Royal Titan kills");
		ALIASES.put("high-level gamble", "High-level Gambles");
		ALIASES.put("barrows chests", "Barrows Chests opened");
	}

	/** Counters RuneLite's chat commands save under a name of their own. */
	private static final Map<String, String> SAVED_AS = new HashMap<>();

	static
	{
		SAVED_AS.put("Barrows Chests opened", "barrows chests");
		SAVED_AS.put("Grand Hallowed Coffins opened", "hallowed sepulchre");
		SAVED_AS.put("Rifts closed", "guardians of the rift");
		SAVED_AS.put("Rumours Completed", "hunter rumours");
	}

	private final Map<String, String> labelsByBase = new HashMap<>();
	private final java.util.Set<String> labels = new java.util.HashSet<>();

	/** @param labels every counter name the odds use */
	public ChatReader(List<String> labels)
	{
		for (String label : labels)
		{
			labelsByBase.put(base(label), label);
			this.labels.add(label);
		}
	}

	/** The item name of a "New item added" message, or null. */
	public static String newSlot(String message)
	{
		Matcher m = NEW_SLOT.matcher(Text.removeTags(message));
		return m.find() ? m.group(1).trim() : null;
	}

	private static final Pattern PAGE_COUNTER = Pattern.compile("^(?<label>[^:]+?):\\s*(?<count>[0-9,]+)$");

	/** A counter line from a collection log page header, such as "Vorkath kills: 312", or null. */
	public static Count pageCounter(String line)
	{
		Matcher m = PAGE_COUNTER.matcher(Text.removeTags(line).trim());
		if (!m.find())
		{
			return null;
		}
		int value = parse(m.group("count"));
		return value < 0 ? null : new Count(m.group("label").trim(), value);
	}

	/** A kill count message read as a collection log counter, or null. */
	public Count count(String message)
	{
		// Some counters arrive with colour shorthand such as @red@ as well as tags.
		String text = Text.removeTags(message).replaceAll("@[a-z]{2,6}@", "");
		Matcher clue = CLUES.matcher(text);
		if (clue.find())
		{
			String tier = clue.group("tier");
			String label = Character.toUpperCase(tier.charAt(0)) + tier.substring(1).toLowerCase(Locale.ENGLISH) + " clues completed";
			return new Count(label, parse(clue.group("count")));
		}
		Count other = fixed(text, COFFINS, "Grand Hallowed Coffins opened");
		other = other != null ? other : fixed(text, RIFTS, "Rifts closed");
		other = other != null ? other : fixed(text, RUMOURS, "Rumours Completed");
		if (other != null)
		{
			return other;
		}
		Matcher m = COUNT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String name = m.group("name").trim();
		String label = labelFor(name);
		return label == null ? null : new Count(label, parse(m.group("count")));
	}

	private Count fixed(String text, Pattern pattern, String label)
	{
		if (!labels.contains(label))
		{
			return null;
		}
		Matcher m = pattern.matcher(text);
		return m.find() ? new Count(label, parse(m.group("count"))) : null;
	}

	/**
	 * Where RuneLite's chat commands may have saved this counter, best guess first. They
	 * save the name as the chat message gives it, lower case and without colons.
	 */
	public static List<String> savedKeys(String label)
	{
		List<String> keys = new java.util.ArrayList<>();
		String saved = SAVED_AS.get(label);
		if (saved != null)
		{
			keys.add(saved);
		}
		keys.add(base(label));
		for (Map.Entry<String, String> alias : ALIASES.entrySet())
		{
			String key = alias.getKey().replace(":", "");
			if (alias.getValue().equals(label) && !keys.contains(key))
			{
				keys.add(key);
			}
		}
		return keys;
	}

	/** The counter a chat name refers to, or null if the log has no such counter. */
	String labelFor(String chatName)
	{
		String key = chatName.trim().toLowerCase(Locale.ENGLISH);
		String alias = ALIASES.get(key);
		if (alias != null)
		{
			return alias;
		}
		String label = labelsByBase.get(key);
		if (label == null && key.startsWith("the "))
		{
			label = labelsByBase.get(key.substring(4));
		}
		return label;
	}

	/** "Vorkath kills" to "vorkath", the key RuneLite's chat commands save counts under. */
	public static String base(String label)
	{
		return SUFFIX.matcher(label.trim()).replaceFirst("").toLowerCase(Locale.ENGLISH);
	}

	private static int parse(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	public static final class Count
	{
		public final String label;
		public final int value;

		Count(String label, int value)
		{
			this.label = label;
			this.value = value;
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * The shape of the collection log as the game defines it: tabs, their pages and the
 * slots on each page, with item names. Read from the game cache once per session, so
 * new pages and slots appear without a plugin update.
 */
public final class LogStructure
{
	@Getter
	private final List<Tab> tabs;
	private final Map<Integer, String> names;
	private final Map<String, List<Integer>> idsByName;
	private final Map<Integer, List<Page>> pagesByItem;
	@Getter
	private final int uniqueSlots;

	public LogStructure(List<Tab> tabs, Map<Integer, String> names)
	{
		this.tabs = Collections.unmodifiableList(new ArrayList<>(tabs));
		this.names = Collections.unmodifiableMap(new HashMap<>(names));
		Map<String, List<Integer>> byName = new HashMap<>();
		Map<Integer, List<Page>> byItem = new HashMap<>();
		Set<Integer> unique = new LinkedHashSet<>();
		for (Tab tab : this.tabs)
		{
			for (Page page : tab.getPages())
			{
				for (int id : page.getItems())
				{
					unique.add(id);
					byItem.computeIfAbsent(id, k -> new ArrayList<>()).add(page);
				}
			}
		}
		for (int id : unique)
		{
			byName.computeIfAbsent(key(name(id)), k -> new ArrayList<>()).add(id);
		}
		this.idsByName = byName;
		this.pagesByItem = byItem;
		this.uniqueSlots = unique.size();
	}

	public static LogStructure empty()
	{
		return new LogStructure(Collections.emptyList(), Collections.emptyMap());
	}

	public boolean isEmpty()
	{
		return tabs.isEmpty();
	}

	public String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null ? "Item " + itemId : name;
	}

	/** Slots with this exact name; several when variants share one, such as coloured ornaments. */
	public List<Integer> idsNamed(String name)
	{
		List<Integer> ids = idsByName.get(key(name));
		return ids == null ? Collections.emptyList() : ids;
	}

	public List<Page> pagesOf(int itemId)
	{
		List<Page> pages = pagesByItem.get(itemId);
		return pages == null ? Collections.emptyList() : pages;
	}

	public Page page(String name)
	{
		for (Tab tab : tabs)
		{
			for (Page page : tab.getPages())
			{
				if (page.getName().equalsIgnoreCase(name))
				{
					return page;
				}
			}
		}
		return null;
	}

	private static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ENGLISH);
	}

	@Getter
	public static final class Tab
	{
		private final String name;
		private final List<Page> pages;

		public Tab(String name, List<Page> pages)
		{
			this.name = name;
			this.pages = Collections.unmodifiableList(new ArrayList<>(pages));
		}
	}

	@Getter
	public static final class Page
	{
		private final String tab;
		private final String name;
		private final List<Integer> items;

		public Page(String tab, String name, List<Integer> items)
		{
			this.tab = tab;
			this.name = name;
			this.items = Collections.unmodifiableList(new ArrayList<>(items));
		}
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/** How a set of slots compares with everyone else at the same counts. */
@Getter
public final class Luck
{
	public enum Verdict
	{
		PARCHED("Parched"),
		DRY("Dry"),
		EVEN("Even"),
		FORTUNATE("Fortunate"),
		BLESSED("Blessed");

		@Getter
		private final String label;

		Verdict(String label)
		{
			this.label = label;
		}
	}

	/** 0 is the driest account possible, 1 the luckiest. */
	private final double percentile;
	/** Slots an average player would own by now. */
	private final double expected;
	private final int owned;
	/** How many slots the read covers. */
	private final int slots;

	public Luck(double percentile, double expected, int owned, int slots)
	{
		this.percentile = percentile;
		this.expected = expected;
		this.owned = owned;
		this.slots = slots;
	}

	public static Luck of(double[] chances, int owned)
	{
		double expected = 0;
		for (double c : chances)
		{
			expected += c;
		}
		return new Luck(Odds.luckPercentile(chances, owned), expected, owned, chances.length);
	}

	public Verdict verdict()
	{
		return verdict(percentile);
	}

	public static Verdict verdict(double percentile)
	{
		if (percentile >= 0.85)
		{
			return Verdict.BLESSED;
		}
		if (percentile >= 0.65)
		{
			return Verdict.FORTUNATE;
		}
		if (percentile > 0.35)
		{
			return Verdict.EVEN;
		}
		return percentile > 0.15 ? Verdict.DRY : Verdict.PARCHED;
	}

	/** Whole percent of players this account is luckier than. */
	public int luckierThan()
	{
		return (int) Math.round(percentile * 100);
	}
}

package com.codex.loginsight.core;

/**
 * The probability behind every number Log Insight shows. Kept free of game types so
 * it can be tested on its own.
 */
public final class Odds
{
	private static final int STEPS = 1600;

	private Odds()
	{
	}

	/**
	 * Where an account sits among everyone at the same counts, from 0 (driest) to 1
	 * (luckiest): the share of players who would own fewer of these slots, counting
	 * half of those who own exactly as many.
	 *
	 * @param chances each slot's chance of being owned by now
	 * @param owned   how many of those slots are owned
	 */
	public static double luckPercentile(double[] chances, int owned)
	{
		int n = chances.length;
		if (n == 0)
		{
			return 0.5;
		}
		// Distribution of the number of owned slots (Poisson binomial), built one slot at a time.
		double[] dist = new double[n + 1];
		dist[0] = 1;
		for (int i = 0; i < n; i++)
		{
			double q = clamp(chances[i]);
			for (int k = i + 1; k >= 1; k--)
			{
				dist[k] = dist[k] * (1 - q) + dist[k - 1] * q;
			}
			dist[0] *= 1 - q;
		}
		owned = Math.max(0, Math.min(n, owned));
		double below = 0;
		for (int k = 0; k < owned; k++)
		{
			below += dist[k];
		}
		return Math.max(0, Math.min(1, below + dist[owned] / 2));
	}

	/**
	 * Expected attempts until any one of these slots arrives: the first success of a roll
	 * with this summed chance per attempt, or the fixed count, whichever comes first.
	 *
	 * @param chanceSum the summed chance per attempt of the slots that can roll
	 * @param exact     attempts until a slot that is earned outright, or infinity
	 */
	public static double attemptsToNext(double chanceSum, double exact)
	{
		if (chanceSum <= 0)
		{
			return exact;
		}
		if (chanceSum >= 1)
		{
			return Math.min(1, exact);
		}
		if (Double.isInfinite(exact))
		{
			return 1 / chanceSum;
		}
		// E[min(T, n)] for a geometric T is the sum of P(T > t) for t below n.
		double attempts = Math.ceil(exact);
		return -Math.expm1(attempts * Math.log1p(-chanceSum)) / chanceSum;
	}

	/**
	 * Expected attempts until every one of these slots is owned, for slots rolled on their
	 * own odds. Each value is one slot's average attempts.
	 */
	public static double attemptsToAll(double[] attempts, double fixed)
	{
		int[] stages = new int[attempts.length];
		java.util.Arrays.fill(stages, 1);
		return attemptsToAll(fixed, attempts, stages);
	}

	/**
	 * Expected attempts until every slot is owned: the expected latest of every waiting time,
	 * integrated numerically.
	 *
	 * @param fixed  attempts spent on slots earned outright (points, permits, milestones), which add up
	 *               because each one is paid for separately
	 * @param means  for each run of rolled slots, its average attempts in total; a run is one slot, or
	 *               several that only drop in order (bludgeon pieces), which wait one after another
	 * @param stages how many slots each run holds
	 */
	public static double attemptsToAll(double fixed, double[] means, int[] stages)
	{
		int n = means.length;
		if (n == 0)
		{
			return fixed;
		}
		double slowest = 0;
		for (double mean : means)
		{
			slowest = Math.max(slowest, mean);
		}
		if (slowest <= 0)
		{
			return fixed;
		}
		// Every run is done by then, apart from a negligible chance.
		double end = fixed + slowest * (Math.log(n) + 14);
		double h = (end - fixed) / STEPS;
		double total = fixed;
		double previous = missing(means, stages, fixed);
		for (int s = 1; s <= STEPS; s++)
		{
			double t = fixed + s * h;
			double current = missing(means, stages, t);
			total += (previous + current) / 2 * h;
			previous = current;
		}
		return total;
	}

	/** The chance that at time t some run still has a slot missing. */
	private static double missing(double[] means, int[] stages, double t)
	{
		double all = 1;
		for (int i = 0; i < means.length; i++)
		{
			all *= runDone(means[i], Math.max(1, stages[i]), t);
		}
		return 1 - all;
	}

	/**
	 * The chance a run of k slots, each waited for in turn, is done by time t. The waits are
	 * taken as equal shares of the run's mean, which makes the total an Erlang wait: much
	 * tighter than one long wait with the same mean, as several pieces in a row really are.
	 */
	static double runDone(double mean, int k, double t)
	{
		if (mean <= 0)
		{
			return 1;
		}
		double x = t * k / mean;
		if (k == 1)
		{
			return -Math.expm1(-x);
		}
		double term = 1;
		double sum = 1;
		for (int j = 1; j < k; j++)
		{
			term *= x / j;
			sum += term;
		}
		return Math.max(0, 1 - Math.exp(-x) * sum);
	}

	private static double clamp(double p)
	{
		return Math.max(0, Math.min(1, p));
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What this account has done, saved per RuneScape profile: owned slots, the
 * collection log's counters, the finds Log Insight saw happen and your own pace.
 * Plain fields so Gson can save it as it is.
 */
public final class Progress
{
	private static final int MAX_FINDS = 40;

	/** Slots known to be owned. Only ever grows; the game never takes a slot back. */
	private Set<Integer> owned = new HashSet<>();
	/** Collection log counters, such as "Vorkath kills" to 312. */
	private Map<String, Integer> counters = new HashMap<>();
	/** Finds seen as they happened, newest first. */
	private List<Find> finds = new ArrayList<>();
	/** Your own pace per counter. */
	private Map<String, Pace> pace = new HashMap<>();
	/** When the whole log was last read from the game, or 0. */
	private long fullReadAt;
	/** Pages whose counters were read from the log itself. */
	private Map<String, Long> pagesRead = new LinkedHashMap<>();
	/** The counter names each read page shows, in its own order. */
	private Map<String, List<String>> pageLabels = new HashMap<>();

	public Progress copy()
	{
		Progress p = new Progress();
		p.owned = new HashSet<>(owned());
		p.counters = new HashMap<>(counters());
		p.finds = new ArrayList<>(finds());
		p.pace = new HashMap<>();
		for (Map.Entry<String, Pace> e : pace().entrySet())
		{
			p.pace.put(e.getKey(), e.getValue().copy());
		}
		p.fullReadAt = fullReadAt;
		p.pagesRead = new LinkedHashMap<>(pagesRead());
		p.pageLabels = new HashMap<>(pageLabels());
		return p;
	}

	// Gson leaves fields null when an older save lacks them, so every read goes through these.

	private Set<Integer> owned()
	{
		if (owned == null)
		{
			owned = new HashSet<>();
		}
		return owned;
	}

	private Map<String, Integer> counters()
	{
		if (counters == null)
		{
			counters = new HashMap<>();
		}
		return counters;
	}

	private List<Find> finds()
	{
		if (finds == null)
		{
			finds = new ArrayList<>();
		}
		return finds;
	}

	private Map<String, Pace> pace()
	{
		if (pace == null)
		{
			pace = new HashMap<>();
		}
		return pace;
	}

	private Map<String, Long> pagesRead()
	{
		if (pagesRead == null)
		{
			pagesRead = new LinkedHashMap<>();
		}
		return pagesRead;
	}

	private Map<String, List<String>> pageLabels()
	{
		if (pageLabels == null)
		{
			pageLabels = new HashMap<>();
		}
		return pageLabels;
	}

	public boolean owns(int itemId)
	{
		return owned().contains(itemId);
	}

	public Set<Integer> getOwned()
	{
		return Collections.unmodifiableSet(owned());
	}

	/** @return true if this slot is new */
	public boolean addOwned(int itemId)
	{
		return owned().add(itemId);
	}

	public Map<String, Integer> getCounters()
	{
		return Collections.unmodifiableMap(counters());
	}

	public Integer counter(String label)
	{
		return counters().get(label);
	}

	/** @return true if the value changed */
	public boolean setCounter(String label, int value)
	{
		Integer old = counters().put(label, value);
		return old == null || old != value;
	}

	public List<Find> getFinds()
	{
		return Collections.unmodifiableList(finds());
	}

	public void addFind(Find find)
	{
		finds().add(0, find);
		while (finds().size() > MAX_FINDS)
		{
			finds().remove(finds().size() - 1);
		}
	}

	public Pace pace(String label)
	{
		return pace().get(label);
	}

	public Pace paceFor(String label)
	{
		return pace().computeIfAbsent(label, k -> new Pace());
	}

	public long getFullReadAt()
	{
		return fullReadAt;
	}

	public void setFullReadAt(long fullReadAt)
	{
		this.fullReadAt = fullReadAt;
	}

	public void markPageRead(String page, long at)
	{
		pagesRead().put(page, at);
	}

	public void setPageLabels(String page, List<String> labels)
	{
		pageLabels().put(page, new ArrayList<>(labels));
	}

	/** Counter names the page showed when it was last read, or null. */
	public List<String> pageLabels(String page)
	{
		List<String> labels = pageLabels().get(page);
		return labels == null ? null : Collections.unmodifiableList(labels);
	}

	public int pagesReadCount()
	{
		return pagesRead().size();
	}

	public boolean isPageRead(String page)
	{
		return pagesRead().containsKey(page);
	}

	/** A slot that arrived while Log Insight was watching. */
	public static final class Find
	{
		private int itemId;
		private String name;
		private String page;
		private String label;
		private int count;
		private double chance;
		/** Share of players who would still be waiting at this count: higher is luckier. */
		private double luckier;
		private long at;

		public Find(int itemId, String name, String page, String label, int count, double chance, double luckier, long at)
		{
			this.itemId = itemId;
			this.name = name;
			this.page = page;
			this.label = label;
			this.count = count;
			this.chance = chance;
			this.luckier = luckier;
			this.at = at;
		}

		public int getItemId()
		{
			return itemId;
		}

		public String getName()
		{
			return name;
		}

		public String getPage()
		{
			return page;
		}

		public String getLabel()
		{
			return label;
		}

		/** Kill count when it dropped, or 0 if unknown. */
		public int getCount()
		{
			return count;
		}

		/** Chance per count, or 0 if unknown. */
		public double getChance()
		{
			return chance;
		}

		/** 0 to 1, or -1 if unknown. */
		public double getLuckier()
		{
			return luckier;
		}

		public long getAt()
		{
			return at;
		}
	}

	/**
	 * Your own speed at one counter, learned from the gaps between kill count messages.
	 * Gaps longer than a break are ignored so banking trips count but logging off does not.
	 */
	public static final class Pace
	{
		static final long MAX_GAP_MS = 12 * 60_000L;
		private static final double WEIGHT = 0.12;

		private double secondsPerCount;
		private int samples;
		private long lastAt;
		private int lastCount;

		Pace copy()
		{
			Pace p = new Pace();
			p.secondsPerCount = secondsPerCount;
			p.samples = samples;
			p.lastAt = lastAt;
			p.lastCount = lastCount;
			return p;
		}

		public void record(int count, long at)
		{
			if (lastAt > 0 && count > lastCount && at > lastAt && at - lastAt <= MAX_GAP_MS * (count - lastCount))
			{
				double seconds = (at - lastAt) / 1000.0 / (count - lastCount);
				secondsPerCount = samples == 0 ? seconds : secondsPerCount + (seconds - secondsPerCount) * WEIGHT;
				samples++;
			}
			lastAt = at;
			lastCount = count;
		}

		public int getSamples()
		{
			return samples;
		}

		/** Completions per hour, or 0 if not learned yet. */
		public double perHour()
		{
			return samples == 0 || secondsPerCount <= 0 ? 0 : 3600 / secondsPerCount;
		}
	}
}

