package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * What this account can do yet: its real skill levels and the quests it still has to
 * finish. Read on the client thread and handed to the analysis as a plain value.
 */
public final class Unlocks
{
	/** Before the account has been read: nothing counts as locked. */
	public static final Unlocks UNKNOWN = new Unlocks(null, Collections.emptySet());

	private final Map<String, Integer> levels;
	private final Set<String> unfinished;

	/**
	 * @param levels     real level by RuneLite skill name, or null when unknown
	 * @param unfinished quests known to be unfinished, by name
	 */
	public Unlocks(Map<String, Integer> levels, Set<String> unfinished)
	{
		this.levels = levels == null ? null : new HashMap<>(levels);
		this.unfinished = new HashSet<>();
		for (String quest : unfinished)
		{
			this.unfinished.add(normalise(quest));
		}
	}

	/** The first thing this activity still needs, such as "85 Slayer", or null when it can be done. */
	public String missing(Activity activity)
	{
		if (levels != null)
		{
			for (Map.Entry<String, Integer> need : activity.getSkills().entrySet())
			{
				Integer level = levels.get(need.getKey());
				if (level != null && level < need.getValue())
				{
					String skill = need.getKey().toLowerCase(Locale.ENGLISH);
					return need.getValue() + " " + Character.toUpperCase(skill.charAt(0)) + skill.substring(1);
				}
			}
		}
		for (String quest : activity.getQuests())
		{
			if (unfinished.contains(normalise(quest)))
			{
				return quest;
			}
		}
		return null;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Unlocks))
		{
			return false;
		}
		Unlocks other = (Unlocks) o;
		return java.util.Objects.equals(levels, other.levels) && unfinished.equals(other.unfinished);
	}

	@Override
	public int hashCode()
	{
		return java.util.Objects.hash(levels, unfinished);
	}

	/** Quest names compared on letters and digits only, so "Heroes' Quest" matches "HEROES_QUEST". */
	public static String normalise(String name)
	{
		return name == null ? "" : name.toUpperCase(Locale.ENGLISH).replaceAll("[^A-Z0-9]", "");
	}
}

package com.codex.loginsight.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;
import lombok.Getter;

/** Something you can repeat to fill log slots: a boss, a raid, a casket, a minigame round. */
@Getter
public final class Activity
{
	public enum Category
	{
		COMBAT("Combat"),
		MINIGAME("Minigames"),
		OTHER("Other");

		@Getter
		private final String label;

		Category(String label)
		{
			this.label = label;
		}

		static Category of(String code)
		{
			if ("C".equals(code))
			{
				return COMBAT;
			}
			return "M".equals(code) ? MINIGAME : OTHER;
		}
	}

	private final int index;
	private final String name;
	private final Category category;
	/** Typical completions per hour on a normal account. */
	private final double perHourMain;
	/** Typical completions per hour for an ironman, who has to supply everything themselves. */
	private final double perHourIron;
	/** One-off hours before the first attempt, such as unlocking the content. */
	private final double setupHours;
	/** In table order, which matters for slots that only drop once the one before is owned. */
	private final List<Drop> drops;
	/** Real skill levels needed, by RuneLite skill name such as "SLAYER". */
	private final Map<String, Integer> skills;
	/** Quests that must be finished, by name. */
	private final List<String> quests;

	public Activity(int index, String name, Category category, double perHourMain, double perHourIron, double setupHours, List<Drop> drops)
	{
		this(index, name, category, perHourMain, perHourIron, setupHours, drops, Collections.emptyMap(), Collections.emptyList());
	}

	public Activity(int index, String name, Category category, double perHourMain, double perHourIron, double setupHours,
		List<Drop> drops, Map<String, Integer> skills, List<String> quests)
	{
		this.skills = Collections.unmodifiableMap(new LinkedHashMap<>(skills));
		this.quests = Collections.unmodifiableList(new ArrayList<>(quests));
		this.index = index;
		this.name = name;
		this.category = category;
		this.perHourMain = perHourMain;
		this.perHourIron = perHourIron;
		this.setupHours = setupHours;
		this.drops = Collections.unmodifiableList(drops);
	}

	public double perHour(boolean iron)
	{
		return iron ? perHourIron : perHourMain;
	}

	/** One slot on an activity's table. */
	@Getter
	public static final class Drop
	{
		private static final int EXACT = 1;
		private static final int INDEPENDENT = 2;
		private static final int SEQUENTIAL = 4;

		private final int activityIndex;
		private final int itemId;
		/** Average attempts per drop, so 512 means 1 in 512. */
		private final double attempts;
		private final int flags;

		public Drop(int activityIndex, int itemId, double attempts, int flags)
		{
			this.activityIndex = activityIndex;
			this.itemId = itemId;
			this.attempts = attempts;
			this.flags = flags;
		}

		/** Earned after a fixed number of attempts (points, permits, a shop) rather than rolled. */
		public boolean isExact()
		{
			return (flags & EXACT) != 0;
		}

		/** Only drops once the slot listed before it on the table is owned (such as bludgeon pieces). */
		public boolean isSequential()
		{
			return (flags & SEQUENTIAL) != 0;
		}

		public boolean isIndependent()
		{
			return (flags & INDEPENDENT) != 0;
		}
	}
}

package com.codex.loginsight.data;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Getter;

/**
 * A slot's chance per kill count, possibly from several counters at once
 * (a gilded item can come from hard, elite or master caskets).
 */
@Getter
public final class ItemOdds
{
	private final List<Roll> rolls;
	/** Kill count at which the slot is guaranteed, or 0. */
	private final int guaranteedBy;

	public ItemOdds(List<Roll> rolls, int guaranteedBy)
	{
		this.rolls = Collections.unmodifiableList(rolls);
		this.guaranteedBy = guaranteedBy;
	}

	/** The counter most of this slot's chance comes from, used to label it. */
	public String mainLabel()
	{
		Roll best = rolls.get(0);
		for (Roll roll : rolls)
		{
			if (roll.chancePerCount() > best.chancePerCount())
			{
				best = roll;
			}
		}
		return best.label;
	}

	/** Chance in one kill count of the main counter, for showing "1 in N". */
	public double mainChance()
	{
		String label = mainLabel();
		double miss = 1;
		for (Roll roll : rolls)
		{
			if (roll.label.equals(label))
			{
				miss *= Math.pow(1 - roll.chance, roll.rolls);
			}
		}
		return 1 - miss;
	}

	/**
	 * The chance of still not having this slot at these counts, or -1 when none of its
	 * counters is known. Counters that are unknown count as zero.
	 */
	public double dryChance(Map<String, Integer> counters)
	{
		boolean known = false;
		double logMiss = 0;
		int main = 0;
		for (Roll roll : rolls)
		{
			Integer count = counters.get(roll.label);
			if (count == null)
			{
				continue;
			}
			known = true;
			logMiss += roll.rolls * (double) count * Math.log1p(-Math.min(roll.chance, 0.999999));
			if (roll.label.equals(mainLabel()))
			{
				main = Math.max(main, count);
			}
		}
		if (!known)
		{
			return -1;
		}
		if (guaranteedBy > 0 && main >= guaranteedBy)
		{
			return 0;
		}
		return Math.exp(logMiss);
	}

	@Getter
	public static final class Roll
	{
		private final String label;
		private final double chance;
		private final int rolls;

		public Roll(String label, double chance, int rolls)
		{
			this.label = label;
			this.chance = chance;
			this.rolls = rolls;
		}

		double chancePerCount()
		{
			return 1 - Math.pow(1 - chance, rolls);
		}
	}
}

package com.codex.loginsight.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The bundled tables: every activity that fills collection log slots, how often it
 * can be done in an hour and what it drops, plus each slot's odds per kill count.
 * Built by tools/build_data.py; see THIRD_PARTY_NOTICES.md for where it comes from.
 */
public final class LogData
{
	private static final String RESOURCE = "/com/codex/loginsight/codex-log.json";

	private final List<Activity> activities;
	private final Map<Integer, List<Activity.Drop>> dropsByItem;
	private final Map<Integer, ItemOdds> odds;
	private final List<String> labels;
	private final Set<Integer> pets;

	public LogData(List<Activity> activities, List<String> labels, Map<Integer, ItemOdds> odds, Set<Integer> pets)
	{
		this.activities = Collections.unmodifiableList(new ArrayList<>(activities));
		this.labels = Collections.unmodifiableList(new ArrayList<>(labels));
		this.odds = Collections.unmodifiableMap(new HashMap<>(odds));
		this.pets = Collections.unmodifiableSet(new HashSet<>(pets));
		Map<Integer, List<Activity.Drop>> byItem = new HashMap<>();
		for (Activity activity : this.activities)
		{
			for (Activity.Drop drop : activity.getDrops())
			{
				byItem.computeIfAbsent(drop.getItemId(), k -> new ArrayList<>()).add(drop);
			}
		}
		this.dropsByItem = byItem;
	}

	public static LogData load(Gson gson) throws IOException
	{
		try (InputStream in = LogData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return fromRaw(gson.fromJson(reader, Raw.class));
			}
		}
	}

	static LogData fromRaw(Raw raw)
	{
		List<Activity> activities = new ArrayList<>();
		for (RawActivity a : raw.activities)
		{
			List<Activity.Drop> drops = new ArrayList<>();
			Map<Integer, Integer> positions = new HashMap<>();
			int index = activities.size();
			for (double[] d : a.d)
			{
				Activity.Drop drop = new Activity.Drop(index, (int) d[0], d[1], (int) d[2]);
				Integer at = positions.putIfAbsent(drop.getItemId(), drops.size());
				if (at == null)
				{
					drops.add(drop);
				}
				else if (better(drop, drops.get(at)))
				{
					// A second row for the same slot is another way to earn it on the same activity (destroying
					// Araxxor instead of looting, buying with points instead of rolling). They are alternatives,
					// not extra rolls, so the slot takes whichever is quicker, in the first row's place.
					drops.set(at, drop);
				}
			}
			Map<String, Integer> skills = a.r == null || a.r.s == null ? Collections.emptyMap() : a.r.s;
			List<String> quests = a.r == null || a.r.q == null ? Collections.emptyList() : a.r.q;
			activities.add(new Activity(index, a.n, Activity.Category.of(a.c), a.m, a.i, a.f, drops, skills, quests));
		}
		Map<Integer, ItemOdds> odds = new HashMap<>();
		for (Map.Entry<String, RawOdds> e : raw.odds.entrySet())
		{
			List<ItemOdds.Roll> rolls = new ArrayList<>();
			for (double[] r : e.getValue().r)
			{
				rolls.add(new ItemOdds.Roll(raw.labels.get((int) r[0]), r[1], (int) r[2]));
			}
			odds.put(Integer.parseInt(e.getKey()), new ItemOdds(rolls, e.getValue().g));
		}
		Set<Integer> pets = new HashSet<>();
		for (int id : raw.pets)
		{
			pets.add(id);
		}
		return new LogData(activities, raw.labels, odds, pets);
	}

	/** True when this row earns its slot sooner than the other, a fixed count winning ties. */
	private static boolean better(Activity.Drop drop, Activity.Drop other)
	{
		if (drop.getAttempts() != other.getAttempts())
		{
			return drop.getAttempts() < other.getAttempts();
		}
		return drop.isExact() && !other.isExact();
	}

	public List<Activity> getActivities()
	{
		return activities;
	}

	/** Every activity row that can drop this item, possibly none. */
	public List<Activity.Drop> dropsOf(int itemId)
	{
		List<Activity.Drop> drops = dropsByItem.get(itemId);
		return drops == null ? Collections.emptyList() : drops;
	}

	public Activity activity(int index)
	{
		return activities.get(index);
	}

	/** Odds per kill count, or null for slots that are bought, guaranteed or not modelled. */
	public ItemOdds odds(int itemId)
	{
		return odds.get(itemId);
	}

	/** Every quest any activity needs, by name. */
	public Set<String> questsNeeded()
	{
		Set<String> quests = new java.util.TreeSet<>();
		for (Activity activity : activities)
		{
			quests.addAll(activity.getQuests());
		}
		return quests;
	}

	/** The collection log counter names the odds refer to, such as "Vorkath kills". */
	public List<String> getLabels()
	{
		return labels;
	}

	public boolean isPet(int itemId)
	{
		return pets.contains(itemId);
	}

	static final class Raw
	{
		List<RawActivity> activities = new ArrayList<>();
		int[] pets = new int[0];
		List<String> labels = new ArrayList<>();
		Map<String, RawOdds> odds = new HashMap<>();
	}

	static final class RawActivity
	{
		String n;
		String c;
		double m;
		double i;
		double f;
		List<double[]> d = new ArrayList<>();
		RawNeeds r;
	}

	static final class RawNeeds
	{
		Map<String, Integer> s;
		List<String> q;
	}

	static final class RawOdds
	{
		List<double[]> r = new ArrayList<>();
		int g;
	}
}

package com.codex.loginsight.overlay;

import com.codex.loginsight.ui.Sigil;
import com.codex.loginsight.ui.Theme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque that rises in the game view when a new slot lands: the item, its odds,
 * the count it came at, and how lucky that was. It draws a view the plugin prepares,
 * so rendering never touches game state.
 */
public class FindPlaque extends Overlay
{
	private static final int WIDTH = 228;
	private static final int PAD = 9;
	private static final int ICON = 40;
	private static final long FADE_MS = 450;

	/** What the plaque shows. */
	public static final class View
	{
		final String name;
		final String page;
		final String odds;
		final String verdict;
		final Color color;
		final boolean pet;
		final BufferedImage icon;
		final long shownAt;
		final long durationMs;

		public View(String name, String page, String odds, String verdict, Color color, boolean pet, BufferedImage icon,
			long shownAt, long durationMs)
		{
			this.name = name;
			this.page = page;
			this.odds = odds;
			this.verdict = verdict;
			this.color = color;
			this.pet = pet;
			this.icon = icon;
			this.shownAt = shownAt;
			this.durationMs = durationMs;
		}
	}

	private volatile View view;

	public FindPlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void clear()
	{
		view = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - v.shownAt;
		if (age > v.durationMs)
		{
			view = null;
			return null;
		}
		float alpha = (float) Math.min(1, Math.min(age / (double) FADE_MS, (v.durationMs - age) / (double) FADE_MS));
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, alpha)));
		Theme.smooth(g);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int lines = 2 + (v.odds == null ? 0 : 1) + (v.verdict == null ? 0 : 1);
		int textHeight = small.getHeight() + bold.getHeight() + (lines - 2) * (small.getHeight() + 1);
		int height = PAD * 2 + Math.max(ICON, textHeight);
		Color tint = v.pet ? Theme.VIOLET : Theme.GOLD;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 12, 12);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238)));
		g.fill(shape);
		double beat = 0.5 + 0.5 * Math.sin(age / 220.0);
		g.setStroke(new BasicStroke(3f));
		g.setColor(Theme.alpha(tint, (int) (40 + beat * 70)));
		g.draw(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(tint, 200));
		g.draw(shape);

		// The item sits in a lit well.
		int wellX = PAD;
		int wellY = (height - ICON) / 2;
		g.setPaint(new RadialGradientPaint(wellX + ICON / 2f, wellY + ICON / 2f, ICON / 2f,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(tint, 110), Theme.alpha(Theme.INK_DEEP, 220)}));
		g.fill(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		g.setColor(Theme.alpha(tint, 170));
		g.draw(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		if (v.icon != null)
		{
			g.drawImage(v.icon, wellX + (ICON - v.icon.getWidth()) / 2, wellY + (ICON - v.icon.getHeight()) / 2, null);
		}
		else
		{
			Sigil.paint(g, wellX + 8, wellY + 8, ICON - 16);
		}

		int x = PAD + ICON + 9;
		int width = WIDTH - x - PAD;
		int y = PAD + Math.max(0, (Math.max(ICON, textHeight) - textHeight) / 2);
		g.setFont(Theme.small());
		shadow(g, v.pet ? "A NEW COMPANION" : "NEW LOG SLOT", x, y + small.getAscent(), tint);
		y += small.getHeight();
		g.setFont(Theme.title());
		shadow(g, clip(v.name, bold, width), x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		y += bold.getHeight();
		g.setFont(Theme.small());
		if (v.odds != null)
		{
			shadow(g, clip(v.odds, small, width), x, y + small.getAscent(), Theme.TEXT_MUTED);
			y += small.getHeight() + 1;
		}
		if (v.verdict != null)
		{
			shadow(g, clip(v.verdict, small, width), x, y + small.getAscent(), v.color);
		}
		g.setComposite(old);
		return new Dimension(WIDTH, height);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.loginsight.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The crest at the top of the panel: a ring for the whole log, the slot count, and
 * three ledgers for finished pages, luck and the hours still ahead.
 */
public class Crest extends JPanel
{
	private final ProgressRing ring = new ProgressRing(70, 7f);
	private final JLabel title = Ui.label("Log Insight", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel slots = Ui.label("Log in to read your log", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger pages = new Ledger("Pages done", true);
	private final Ledger luck = new Ledger("Luck", false);
	private final Ledger left = new Ledger("Hours left", false);
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		add(ringHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		slots.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(slots);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(pages);
		ledgers.add(luck);
		ledgers.add(left);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		ring.setCaption("logged");
		ring.setProgress(0, false, false);
	}

	public void update(Report report, String playerName)
	{
		if (!report.isLoggedIn())
		{
			title.setText("Log Insight");
			slots.setText("Log in to read your log");
			ring.setProgress(0, false, true);
			pages.set("-", 0, Theme.TEXT);
			luck.set("-", -1, Theme.TEXT);
			left.set("-", -1, Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		int owned = report.owned();
		int total = report.total();
		title.setText(playerName == null ? "Log Insight" : playerName);
		slots.setText(total <= 0 ? "Reading the log..." : Format.count(owned) + " / " + Format.count(total) + " slots");
		ring.setProgress(total <= 0 ? 0 : owned / (double) total, total > 0 && owned >= total, true);
		pages.set(report.getPagesComplete() + "/" + report.getPagesTotal(),
			report.getPagesTotal() == 0 ? 0 : report.getPagesComplete() / (double) report.getPagesTotal(), Theme.TEXT);
		Luck l = report.getLuck();
		if (l == null)
		{
			luck.set("Unread", -1, Theme.TEXT_MUTED);
			glow = Theme.GOLD_DIM;
		}
		else
		{
			Color c = Theme.luck(l.verdict());
			luck.set(l.verdict().getLabel(), -1, c);
			glow = Theme.mix(Theme.GOLD_DIM, c, 0.45);
		}
		left.set(Format.hours(report.getHoursLeft()), -1, Theme.TEXT);
		left.setToolTipText(report.isIronRates() ? "At ironman rates" : "At typical rates, or your own pace where Log Insight has learned it");
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value, with a hairline bar under it when the value is a share of something. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);
		private final ProgressBar bar;

		Ledger(String label, boolean withBar)
		{
			super(new BorderLayout(0, 1));
			setOpaque(false);
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			line.add(value, BorderLayout.EAST);
			add(line, BorderLayout.CENTER);
			bar = withBar ? new ProgressBar(3) : null;
			if (bar != null)
			{
				add(bar, BorderLayout.SOUTH);
			}
			setPreferredSize(new Dimension(10, 17));
		}

		void set(String text, double share, Color color)
		{
			value.setText(text);
			value.setForeground(color);
			if (bar != null)
			{
				bar.setProgress(Math.max(0, share), share >= 1, true);
			}
		}
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every page of the log, grouped by tab, each with its progress, kill count and luck. */
final class FoliosView
{
	private FoliosView()
	{
	}

	static StackPanel build(Report report, String filter, Consumer<String> openPage)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to see your log page by page.", 190));
			return stack;
		}
		if (report.getPages().isEmpty())
		{
			stack.add(Rows.note("Reading the log's pages from the game...", 190));
			return stack;
		}
		String needle = filter == null ? "" : filter.trim().toLowerCase(Locale.ENGLISH);
		Map<String, List<Report.PageReport>> byTab = new LinkedHashMap<>();
		for (Report.PageReport page : report.getPages())
		{
			if (needle.isEmpty() || page.getName().toLowerCase(Locale.ENGLISH).contains(needle) || matchesItem(page, needle))
			{
				byTab.computeIfAbsent(page.getTab(), k -> new ArrayList<>()).add(page);
			}
		}
		if (byTab.isEmpty())
		{
			stack.add(Rows.note("No page or slot matches \"" + filter.trim() + "\".", 190));
			return stack;
		}
		for (Map.Entry<String, List<Report.PageReport>> tab : byTab.entrySet())
		{
			int done = 0;
			for (Report.PageReport page : tab.getValue())
			{
				done += page.isComplete() ? 1 : 0;
			}
			stack.add(new SectionHeader(tab.getKey(), done + "/" + tab.getValue().size()));
			for (Report.PageReport page : tab.getValue())
			{
				stack.add(row(page).onClick(() -> openPage.accept(page.getName())));
			}
		}
		return stack;
	}

	private static boolean matchesItem(Report.PageReport page, String needle)
	{
		for (Report.ItemReport item : page.getItems())
		{
			if (item.getName().toLowerCase(Locale.ENGLISH).contains(needle))
			{
				return true;
			}
		}
		return false;
	}

	static Card row(Report.PageReport page)
	{
		Card card = new Card(new BorderLayout(0, 3));
		card.setBorder(new EmptyBorder(6, 10, 7, 10));
		if (page.isComplete())
		{
			card.accent(Theme.GREEN);
		}
		else if (page.getLuck() != null)
		{
			card.accent(Theme.luck(page.getLuck().verdict()));
		}

		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.add(Ui.label(page.getName(), Theme.body(), page.isComplete() ? Theme.GOLD_BRIGHT : Theme.TEXT), BorderLayout.CENTER);
		line.add(Ui.label(page.getOwned() + "/" + page.getTotal(), Theme.small(), page.isComplete() ? Theme.GREEN : Theme.TEXT_MUTED),
			BorderLayout.EAST);
		card.add(line, BorderLayout.NORTH);

		ProgressBar bar = new ProgressBar(4);
		bar.setProgress(page.progress(), page.isComplete(), false);
		card.add(bar, BorderLayout.CENTER);

		JPanel meta = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		meta.setOpaque(false);
		if (page.getLuck() != null && !page.isComplete())
		{
			meta.add(new Pill(page.getLuck().verdict().getLabel(), Theme.luck(page.getLuck().verdict())));
		}
		if (page.getCount() >= 0)
		{
			meta.add(Ui.label(Format.count(page.getCount()) + " kc", Theme.small(), Theme.TEXT_MUTED));
		}
		if (!page.isComplete() && Double.isFinite(page.getHoursToNext()))
		{
			meta.add(Ui.label("next " + Format.about(page.getHoursToNext()), Theme.small(), Theme.TEXT_FAINT));
		}
		if (meta.getComponentCount() > 0)
		{
			((FlowLayout) meta.getLayout()).setHgap(5);
			card.add(meta, BorderLayout.SOUTH);
		}
		return card;
	}
}

package com.codex.loginsight.ui;

/** Turns hours, odds and counts into the short phrases the panel uses. */
public final class Format
{
	private Format()
	{
	}

	/** "<1m", "45m", "3h 12m", "120h" or "8,420h"; "-" when it cannot be estimated. */
	public static String hours(double hours)
	{
		if (Double.isNaN(hours) || Double.isInfinite(hours) || hours < 0)
		{
			return "-";
		}
		double minutes = hours * 60;
		if (minutes < 1)
		{
			return "<1m";
		}
		if (minutes < 60)
		{
			return Math.round(minutes) + "m";
		}
		if (hours < 10)
		{
			long h = (long) hours;
			long m = Math.round((hours - h) * 60);
			if (m == 60)
			{
				h++;
				m = 0;
			}
			return m == 0 ? h + "h" : h + "h " + m + "m";
		}
		return String.format("%,dh", Math.round(hours));
	}

	/** "about 3h", or "under 1m" when it is that short. */
	public static String about(double hours)
	{
		String text = hours(hours);
		if (text.startsWith("<"))
		{
			return "under " + text.substring(1);
		}
		return "-".equals(text) ? text : "~" + text;
	}

	/** "1/512", or "1/3.4" for common drops; "-" when unknown. */
	public static String chance(double chance)
	{
		if (chance <= 0 || Double.isNaN(chance))
		{
			return "-";
		}
		double in = 1 / chance;
		if (in < 1.05)
		{
			return "Always";
		}
		if (in < 10 && Math.abs(in - Math.round(in)) >= 0.05)
		{
			return String.format("1/%.1f", in);
		}
		return String.format("1/%,d", Math.round(in));
	}

	/**
	 * How dry a missing slot is, the way players say it: the share of players who would
	 * already have it at this kill count. "88% dry" means 88 in 100 would have it by now.
	 *
	 * @param stillWaiting the share of players still without it
	 */
	public static String dry(double stillWaiting)
	{
		return percent(1 - stillWaiting) + " dry";
	}

	public static String count(long value)
	{
		return String.format("%,d", value);
	}

	/** Whole percent, with "<1%" and ">99%" at the ends so rare cases never read as 0 or 100. */
	public static String percent(double share)
	{
		if (share <= 0)
		{
			return "0%";
		}
		if (share < 0.01)
		{
			return "<1%";
		}
		if (share > 0.99 && share < 1)
		{
			return ">99%";
		}
		return Math.round(share * 100) + "%";
	}

	/** "just now", "5m ago", "3h ago", "2d ago". */
	public static String ago(long then, long now)
	{
		long seconds = Math.max(0, (now - then) / 1000);
		if (seconds < 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return seconds / 60 + "m ago";
		}
		if (seconds < 86400)
		{
			return seconds / 3600 + "h ago";
		}
		return seconds / 86400 + "d ago";
	}

	/** "Vorkath kills" to "Vorkath", for compact lines that already say "kc". */
	public static String counterName(String label)
	{
		if (label == null)
		{
			return "";
		}
		return label.replaceAll("(?i) (kills|completions|completion count|opened|completed)$", "");
	}

	private static final java.util.regex.Pattern LEAD_VERB =
		java.util.regex.Pattern.compile("^(?i)(killing|defeating|looting|opening|finishing|completing) (the )?");
	private static final java.util.Set<String> SMALL_WORDS = new java.util.HashSet<>(java.util.Arrays.asList(
		"of", "the", "and", "at", "in", "on", "from", "with", "for", "to", "a", "an", "or", "by"));

	/**
	 * Where a slot comes from, as a short name: "Killing king black dragon" reads "King Black
	 * Dragon", "Opening hard caskets" reads "Hard Caskets". The bracketed detail is left out.
	 */
	public static String source(String name)
	{
		String text = LEAD_VERB.matcher(activity(name)).replaceFirst("");
		StringBuilder out = new StringBuilder();
		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}
			boolean small = out.length() > 0 && SMALL_WORDS.contains(word.toLowerCase(java.util.Locale.ENGLISH));
			out.append(out.length() > 0 ? " " : "")
				.append(small ? word : Character.toUpperCase(word.charAt(0)) + word.substring(1));
		}
		return out.length() == 0 ? name : out.toString();
	}

	/** The bracketed detail of an activity name, such as "on task" or "300", or null. */
	public static String detail(String name)
	{
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\(([^)]*)\\)").matcher(name);
		if (!m.find())
		{
			return null;
		}
		String detail = m.group(1).trim();
		// Tombs of Amascut rows differ only by raid level.
		return detail.matches("[0-9]+") && name.toLowerCase(java.util.Locale.ENGLISH).contains("amascut")
			? "raid level " + detail : detail;
	}

	/** An activity name for a card title: the parenthetical detail moves to the tooltip. */
	public static String activity(String name)
	{
		String shortName = name.replaceAll("\\s*\\([^)]*\\)", "").replaceAll("\\s+", " ").trim();
		return shortName.isEmpty() ? name : Character.toUpperCase(shortName.charAt(0)) + shortName.substring(1);
	}
}

package com.codex.loginsight.ui;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** An item picture sitting in a small dark well, used at the start of list rows. */
class IconBadge extends JComponent
{
	private final boolean owned;
	private BufferedImage image;

	IconBadge(int itemId, ItemIcons icons, boolean owned)
	{
		this.owned = owned;
		Dimension d = new Dimension(28, 26);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null && itemId > 0)
		{
			image = icons.icon(itemId, this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		g.setColor(Theme.alpha(owned ? Theme.GOLD : Theme.STROKE, owned ? 120 : 200));
		g.draw(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		if (image != null)
		{
			int iw = Math.min(image.getWidth(), 36);
			int ih = Math.min(image.getHeight(), 32);
			double scale = Math.min((w - 2) / (double) iw, (h - 2) / (double) ih);
			int dw = (int) Math.round(iw * scale);
			int dh = (int) Math.round(ih * scale);
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
			}
			g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
		}
		g.dispose();
	}
}

