package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One slot as a small inlaid tile: owned slots sit bright on a gilt rim, missing ones
 * are a faded ghost, with a coloured bead when the wait has run long.
 */
public class ItemTile extends JComponent
{
	public static final int SIZE = 38;

	private final Report.ItemReport item;
	private BufferedImage image;

	public ItemTile(Report.ItemReport item, ItemIcons icons)
	{
		this.item = item;
		Dimension d = new Dimension(SIZE, SIZE - 4);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null)
		{
			image = icons.icon(item.getItemId(), this::repaint);
		}
		setToolTipText(tooltip(item));
	}

	static String tooltip(Report.ItemReport item)
	{
		StringBuilder sb = new StringBuilder("<html><b>").append(Ui.escape(item.getName())).append("</b>");
		if (item.isOwned())
		{
			sb.append("<br>Owned");
		}
		if (item.getChance() > 0)
		{
			sb.append("<br>").append(Format.chance(item.getChance()));
			if (item.getLabel() != null)
			{
				sb.append(" per ").append(Ui.escape(Format.counterName(item.getLabel()))).append(" kc");
			}
		}
		if (!item.isOwned() && item.getDryChance() >= 0)
		{
			sb.append("<br>").append(Format.dry(item.getDryChance())).append(": ")
				.append(Format.percent(1 - item.getDryChance())).append(" of players would have it by now");
		}
		if (!item.isOwned() && item.getSource() != null)
		{
			sb.append("<br>Fastest: ").append(Ui.escape(item.getSource())).append(" (").append(Format.hours(item.getHours())).append(")");
		}
		return sb.append("</html>").toString();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		boolean owned = item.isOwned();
		g.setPaint(new GradientPaint(0, 0, owned ? Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.18) : Theme.INK_DEEP, 0, h,
			owned ? Theme.CARD : Theme.INK_DEEP));
		g.fill(shape);
		Color rim = owned ? (item.isPet() ? Theme.VIOLET : Theme.alpha(Theme.GOLD, 170)) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		if (image != null)
		{
			int iw = image.getWidth();
			int ih = image.getHeight();
			int x = (w - iw) / 2;
			int y = (h - ih) / 2;
			Composite old = g.getComposite();
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.28f));
			}
			g.drawImage(image, x, y, null);
			g.setComposite(old);
		}

		if (!owned && item.getDryChance() >= 0 && item.getDryChance() < 0.35)
		{
			Color bead = Theme.dry(item.getDryChance());
			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(w - 10, 2, 8, 8));
			g.setColor(bead);
			g.fill(new Ellipse2D.Float(w - 9, 3, 6, 6));
		}
		if (owned)
		{
			g.setStroke(new BasicStroke(1f));
			g.setColor(Theme.alpha(Color.WHITE, 18));
			g.drawLine(5, 1, w - 5, 1);
		}
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Progress;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The log at a glance: luck, the numbers, the best hunts, the longest waits and recent finds. */
final class LedgerView
{
	private static final int WIDTH = 190;

	private LedgerView()
	{
	}

	static StackPanel build(Report report, LuckDial dial, ItemIcons icons, Consumer<String> openPage, Runnable openQuarry, long now)
	{
		StackPanel stack = new StackPanel(6, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in and Log Insight will read your collection log.", WIDTH));
			return stack;
		}

		if (report.needsFullRead())
		{
			stack.add(callout("Read your whole log",
				"Open your collection log and press its Search button once. Log Insight reads every slot you own from it, "
					+ "and each page you open also refreshes that page's kill counts."));
		}

		Card dialCard = new Card(new BorderLayout());
		dialCard.setBorder(new EmptyBorder(8, 8, 8, 8));
		dial.setLuck(report.getLuck(), true);
		dialCard.add(dial, BorderLayout.CENTER);
		Luck luck = report.getLuck();
		if (luck != null)
		{
			dialCard.setToolTipText("<html>Across " + luck.getSlots() + " slots with known odds and kill counts.<br>"
				+ "An average player would own " + Math.round(luck.getExpected()) + " of them; you own " + luck.getOwned() + ".</html>");
		}
		stack.add(dialCard);

		// The crest already carries slots, pages and hours; the tiles add what it cannot say.
		List<Report.Hunt> hunts = new java.util.ArrayList<>();
		for (Report.Hunt hunt : report.getHunts())
		{
			if (hunt.getLockedBy() == null && hunts.size() < 3)
			{
				hunts.add(hunt);
			}
		}
		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		if (luck != null)
		{
			long diff = Math.round(luck.getOwned() - luck.getExpected());
			tiles.add(new StatTile((diff > 0 ? "+" : "") + diff, "Vs average", "at your counts",
				diff >= 0 ? Theme.GREEN : Theme.EMBER));
		}
		else
		{
			tiles.add(new StatTile("-", "Vs average", "needs kill counts", Theme.TEXT_MUTED));
		}
		if (hunts.isEmpty())
		{
			tiles.add(new StatTile("-", "Next slot", "nothing rated", Theme.TEXT_MUTED));
		}
		else
		{
			tiles.add(new StatTile(Format.hours(hunts.get(0).getHoursToNext()), "Next slot",
				Format.source(hunts.get(0).getName()), Theme.TEAL));
		}
		int pets = 0;
		int petsOwned = 0;
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (Report.PageReport page : report.getPages())
		{
			for (Report.ItemReport item : page.getItems())
			{
				if (item.isPet() && seen.add(item.getItemId()))
				{
					pets++;
					petsOwned += item.isOwned() ? 1 : 0;
				}
			}
		}
		tiles.add(new StatTile(petsOwned + "/" + pets, "Pets", pets == petsOwned ? "every one" : (pets - petsOwned) + " to go",
			Theme.VIOLET));
		tiles.add(new StatTile(report.getPagesRead() + "/" + report.getPagesTotal(), "Pages read",
			report.getPagesRead() < report.getPagesTotal() ? "open more for luck" : "all kill counts", Theme.GOLD));
		stack.add(tiles);

		if (!hunts.isEmpty())
		{
			stack.add(new SectionHeader("Best next hunts", "all in Quarry"));
			for (int i = 0; i < hunts.size(); i++)
			{
				stack.add(QuarryView.row(hunts.get(i), i + 1, icons).onClick(openQuarry));
			}
		}

		if (!report.getDriest().isEmpty())
		{
			stack.add(new SectionHeader("Longest waits"));
			for (Report.ItemReport item : report.getDriest())
			{
				Card card = PageView.missingRow(item, icons, true);
				if (item.getPage() != null)
				{
					card.onClick(() -> openPage.accept(item.getPage()));
				}
				stack.add(card);
			}
		}

		List<Progress.Find> finds = report.getFinds();
		stack.add(new SectionHeader("Recent finds"));
		if (finds.isEmpty())
		{
			stack.add(Rows.note("New slots will be written here as they drop, with how lucky each one was.", WIDTH));
		}
		else
		{
			for (int i = 0; i < Math.min(6, finds.size()); i++)
			{
				stack.add(findRow(finds.get(i), icons, now));
			}
		}
		return stack;
	}

	static Card callout(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 3));
		card.accent(Theme.GOLD).highlighted(true);
		card.setBorder(new EmptyBorder(7, 10, 8, 10));
		card.add(Ui.label(title, Theme.body(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT, 170), BorderLayout.CENTER);
		return card;
	}

	/** A find: what, the odds and count it came at, then how lucky it was and when. */
	private static JComponent findRow(Progress.Find find, ItemIcons icons, long now)
	{
		StringBuilder detail = new StringBuilder();
		if (find.getChance() > 0)
		{
			detail.append(Format.chance(find.getChance()));
		}
		if (find.getCount() > 0)
		{
			detail.append(detail.length() > 0 ? " at " : "").append(Format.count(find.getCount())).append(" kc");
		}
		if (detail.length() == 0 && find.getPage() != null)
		{
			detail.append(find.getPage());
		}
		String when = Format.ago(find.getAt(), now);
		boolean known = find.getLuckier() >= 0;
		String verdict = known ? "Luckier than " + Math.round(find.getLuckier() * 100) + "%  ·  " + when : when;
		Color color = known ? Theme.luck(find.getLuckier()) : Theme.GOLD;
		return Rows.line(new IconBadge(find.getItemId(), icons, true), find.getName(), detail.toString(), verdict,
			known ? color : Theme.TEXT_FAINT, null, color);
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Graphics;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Log Insight side panel: the crest, then three pages. Ledger is the log at a
 * glance, Folios is the log page by page, and Quarry ranks where the next slots are.
 */
public class LogInsightPanel extends PluginPanel
{
	private static final String[] TABS = {"ledger", "folios", "quarry"};

	private final ItemIcons icons;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Ledger", "Folios", "Quarry");
	private final Segmented quarryFilter = new Segmented(false, QuarryView.FILTERS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane ledger = scroller();
	private final JScrollPane folios = scroller();
	private final JScrollPane quarry = scroller();
	private final JPanel folioHolder = new JPanel(new BorderLayout());
	private final JPanel searchHolder = new JPanel(new BorderLayout());
	private final LuckDial dial = new LuckDial(112);

	/** Tabs whose view was built from an older report and is rebuilt when next shown. */
	private final boolean[] stale = new boolean[TABS.length];
	private int shown;
	private Report report = Report.loggedOut();
	private String playerName;
	private String filter = "";
	private String openPage;

	public LogInsightPanel(ItemIcons icons)
	{
		super(false);
		this.icons = icons;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		searchHolder.setOpaque(false);
		searchHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		searchHolder.add(new SearchField(text ->
		{
			filter = text;
			rebuildFolios();
		}), BorderLayout.CENTER);
		folioHolder.setOpaque(false);
		folioHolder.add(searchHolder, BorderLayout.NORTH);
		folioHolder.add(folios, BorderLayout.CENTER);

		JPanel quarryHolder = new JPanel(new BorderLayout());
		quarryHolder.setOpaque(false);
		JPanel filterHolder = new JPanel(new BorderLayout());
		filterHolder.setOpaque(false);
		filterHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		filterHolder.add(quarryFilter, BorderLayout.CENTER);
		quarryHolder.add(filterHolder, BorderLayout.NORTH);
		quarryHolder.add(quarry, BorderLayout.CENTER);

		content.setOpaque(false);
		content.add(ledger, TABS[0]);
		content.add(folioHolder, TABS[1]);
		content.add(quarryHolder, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		quarryFilter.onChange(i -> rebuildQuarry());
		rebuildTab(0);
		rebuildTab(1);
		rebuildTab(2);
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		Scrollbars.style(scroll.getVerticalScrollBar());
		return scroll;
	}

	/** Called on the Swing thread with each new report. */
	public void update(Report report, String playerName)
	{
		this.report = report;
		this.playerName = playerName;
		rebuild();
	}

	/** Opens the Folios tab at one page, for example the page a new slot landed on. */
	public void showPage(String page)
	{
		openPage = page;
		tabs.setSelected(1, false);
		shown = 1;
		cards.show(content, TABS[1]);
		rebuildFolios();
		SwingUtilities.invokeLater(() -> folios.getVerticalScrollBar().setValue(0));
	}

	/** Switches to a tab, rebuilding it first if a newer report arrived while it was hidden. */
	public void showTab(int tab)
	{
		tabs.setSelected(tab, false);
		shown = tab;
		if (stale[tab])
		{
			rebuildTab(tab);
		}
		cards.show(content, TABS[tab]);
	}

	/** Only the tab in view is rebuilt for each report; the others wait until they are opened. */
	private void rebuild()
	{
		crest.update(report, playerName);
		java.util.Arrays.fill(stale, true);
		rebuildTab(shown);
	}

	private void rebuildTab(int tab)
	{
		stale[tab] = false;
		if (tab == 0)
		{
			replace(ledger, LedgerView.build(report, dial, icons, this::showPage, () -> showTab(2),
				System.currentTimeMillis()));
		}
		else if (tab == 1)
		{
			rebuildFolios();
		}
		else
		{
			rebuildQuarry();
		}
	}

	private void rebuildFolios()
	{
		Report.PageReport page = null;
		if (openPage != null)
		{
			for (Report.PageReport p : report.getPages())
			{
				if (p.getName().equals(openPage))
				{
					page = p;
					break;
				}
			}
		}
		searchHolder.setVisible(page == null);
		if (page != null)
		{
			replace(folios, PageView.build(page, icons, () ->
			{
				openPage = null;
				rebuildFolios();
			}));
		}
		else
		{
			openPage = null;
			replace(folios, FoliosView.build(report, filter, name ->
			{
				openPage = name;
				rebuildFolios();
				SwingUtilities.invokeLater(() -> folios.getVerticalScrollBar().setValue(0));
			}));
		}
		folioHolder.revalidate();
	}

	private void rebuildQuarry()
	{
		replace(quarry, QuarryView.build(report, quarryFilter.getSelected(), icons));
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/**
 * A half-moon gauge from parched to blessed with a gilt needle at where the account
 * stands, and the verdict written underneath.
 */
public class LuckDial extends JComponent
{
	private static final String[] ENDS = {"PARCHED", "BLESSED"};

	private final Animator needle = new Animator(this);
	private final int height;
	private Luck luck;

	public LuckDial(int height)
	{
		this.height = height;
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setOpaque(false);
		needle.set(0.5, false);
	}

	public void setLuck(Luck luck, boolean animate)
	{
		this.luck = luck;
		needle.set(luck == null ? 0.5 : luck.getPercentile(), animate);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();

		// Below the hub sit the end labels' gap, the verdict and the percentile line.
		int textBlock = small.getHeight() + 4 + bold.getHeight() + small.getHeight() + 2;
		float thickness = 9;
		float radius = Math.max(20, Math.min(w / 2f - 14, getHeight() - textBlock - thickness / 2 - 4));
		float cx = w / 2f;
		float cy = thickness / 2 + 4 + radius;
		Arc2D.Float box = new Arc2D.Float(cx - radius, cy - radius, radius * 2, radius * 2, 180, -180, Arc2D.OPEN);

		// The track, in short segments so the colour can travel from blood to green.
		g.setStroke(new BasicStroke(thickness + 4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(box);
		int segments = 60;
		boolean known = luck != null;
		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < segments; i++)
		{
			double t = (i + 0.5) / segments;
			Color c = Theme.luck(t);
			g.setColor(known ? Theme.alpha(c, 215) : Theme.alpha(Theme.STROKE, 200));
			g.draw(new Arc2D.Double(cx - radius, cy - radius, radius * 2, radius * 2, 180 - i * 180.0 / segments, -180.0 / segments - 0.4, Arc2D.OPEN));
		}
		// Tick marks at the verdict borders.
		g.setStroke(new BasicStroke(1.2f));
		for (double edge : new double[]{0.15, 0.35, 0.65, 0.85})
		{
			double a = Math.PI * (1 - edge);
			float inner = radius - thickness / 2 - 2;
			float outer = radius + thickness / 2 + 2;
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.drawLine(Math.round(cx + (float) Math.cos(a) * inner), Math.round(cy - (float) Math.sin(a) * inner),
				Math.round(cx + (float) Math.cos(a) * outer), Math.round(cy - (float) Math.sin(a) * outer));
		}
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.setStroke(new BasicStroke(1f));
		g.draw(new Arc2D.Float(cx - radius - thickness / 2 - 3, cy - radius - thickness / 2 - 3, (radius + thickness / 2 + 3) * 2,
			(radius + thickness / 2 + 3) * 2, 180, -180, Arc2D.OPEN));

		if (known)
		{
			double value = needle.get();
			double a = Math.PI * (1 - value);
			float len = radius - thickness / 2 - 4;
			float tipX = cx + (float) Math.cos(a) * len;
			float tipY = cy - (float) Math.sin(a) * len;
			float baseW = 3.2f;
			Path2D hand = new Path2D.Float();
			hand.moveTo(tipX, tipY);
			hand.lineTo(cx + (float) Math.cos(a + Math.PI / 2) * baseW, cy - (float) Math.sin(a + Math.PI / 2) * baseW);
			hand.lineTo(cx + (float) Math.cos(a - Math.PI / 2) * baseW, cy - (float) Math.sin(a - Math.PI / 2) * baseW);
			hand.closePath();
			g.setColor(Theme.alpha(java.awt.Color.BLACK, 120));
			g.translate(1, 1);
			g.fill(hand);
			g.translate(-1, -1);
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(hand);
			g.setColor(Theme.luck(value));
			g.fill(new Ellipse2D.Float(tipX - 2.5f, tipY - 2.5f, 5, 5));
		}
		g.setColor(Theme.GOLD);
		g.fill(new Ellipse2D.Float(cx - 5, cy - 5, 10, 10));
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(cx - 2, cy - 2, 4, 4));

		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(ENDS[0], Math.max(0, cx - radius - small.stringWidth(ENDS[0]) / 2f), cy + small.getAscent() + 2);
		g.drawString(ENDS[1], Math.min(w - small.stringWidth(ENDS[1]), cx + radius - small.stringWidth(ENDS[1]) / 2f), cy + small.getAscent() + 2);

		int y = Math.round(cy + small.getHeight() + 4);
		String verdict = known ? luck.verdict().getLabel() : "Not read yet";
		String line = known ? "Luckier than " + luck.luckierThan() + "% of players" : "Open log pages to learn your kill counts";
		g.setFont(Theme.title());
		ProgressRing.drawShadowed(g, verdict, Math.round(cx - bold.stringWidth(verdict) / 2f), y + bold.getAscent(),
			known ? Theme.luck(luck.verdict()) : Theme.TEXT_MUTED);
		g.setFont(Theme.small());
		ProgressRing.drawShadowed(g, line, Math.round(cx - small.stringWidth(line) / 2f), y + bold.getHeight() + small.getAscent(), Theme.TEXT_MUTED);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A drawn verdict: a sealed check, a warning, a cross, a quiet note, or an empty dashed ring. */
public class Mark extends JComponent
{
	public enum Kind
	{
		GOOD,
		NOTE,
		WARN,
		BAD,
		NONE
	}

	private final Kind kind;
	private final int size;

	public Mark(Kind kind, int size)
	{
		this.kind = kind;
		this.size = size;
		Dimension d = new Dimension(size, size);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	public static Color color(Kind kind)
	{
		switch (kind)
		{
			case GOOD:
				return Theme.GREEN;
			case WARN:
				return Theme.EMBER;
			case BAD:
				return Theme.BLOOD;
			case NOTE:
				return Theme.GOLD;
			default:
				return Theme.TEXT_FAINT;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, kind, 0, 0, size);
		g.dispose();
	}

	/** Draws a mark anywhere, so the overlay can use the same shapes as the panel. */
	public static void paint(Graphics2D g, Kind kind, float x, float y, int size)
	{
		float s = size - 2;
		float o = 1;
		Color c = color(kind);
		Ellipse2D circle = new Ellipse2D.Float(x + o, y + o, s, s);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		switch (kind)
		{
			case GOOD:
			{
				g.setColor(Theme.alpha(c, 60));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				Path2D check = new Path2D.Float();
				check.moveTo(x + o + s * 0.28, y + o + s * 0.52);
				check.lineTo(x + o + s * 0.44, y + o + s * 0.68);
				check.lineTo(x + o + s * 0.74, y + o + s * 0.34);
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.draw(check);
				break;
			}
			case WARN:
			{
				Path2D tri = new Path2D.Float();
				tri.moveTo(x + o + s / 2, y + o + s * 0.04);
				tri.lineTo(x + o + s, y + o + s * 0.94);
				tri.lineTo(x + o, y + o + s * 0.94);
				tri.closePath();
				g.setColor(Theme.alpha(c, 60));
				g.fill(tri);
				g.setColor(c);
				g.draw(tri);
				g.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + o + s / 2), Math.round(y + o + s * 0.36f), Math.round(x + o + s / 2), Math.round(y + o + s * 0.6f));
				g.fill(new Ellipse2D.Float(x + o + s / 2 - 1.1f, y + o + s * 0.72f, 2.2f, 2.2f));
				break;
			}
			case BAD:
			{
				g.setColor(Theme.alpha(c, 70));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				float a = s * 0.32f;
				float m = s / 2 + o;
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + m - a), Math.round(y + m - a), Math.round(x + m + a), Math.round(y + m + a));
				g.drawLine(Math.round(x + m + a), Math.round(y + m - a), Math.round(x + m - a), Math.round(y + m + a));
				break;
			}
			case NOTE:
			{
				g.setColor(Theme.alpha(c, 40));
				g.fill(circle);
				g.setColor(Theme.alpha(c, 170));
				g.draw(circle);
				float dot = s * 0.34f;
				g.setColor(c);
				g.fill(new Ellipse2D.Float(x + o + (s - dot) / 2, y + o + (s - dot) / 2, dot, dot));
				break;
			}
			default:
			{
				g.setColor(c);
				g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1, new float[]{2f, 2f}, 0));
				g.draw(circle);
			}
		}
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** One page in depth: its counts and luck, the wait for the next slot, and every slot with its odds. */
final class PageView
{
	private static final int COLUMNS = 5;

	private PageView()
	{
	}

	static StackPanel build(Report.PageReport page, ItemIcons icons, Runnable back)
	{
		StackPanel stack = new StackPanel(6, 8);
		JPanel top = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		top.setOpaque(false);
		top.add(new CodexButton("< All pages", false, back));
		stack.add(top);

		Card head = new Card(new BorderLayout(10, 0));
		head.setBorder(new EmptyBorder(9, 10, 9, 10));
		head.highlighted(true);
		ProgressRing ring = new ProgressRing(54, 6f);
		ring.setProgress(page.progress(), page.isComplete(), false);
		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		head.add(ringHolder, BorderLayout.WEST);
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label(page.getTab().toUpperCase(), Theme.small(), Theme.GOLD));
		text.add(Ui.wrapped(page.getName(), Theme.title(), Theme.GOLD_BRIGHT, 120));
		text.add(Ui.label(page.getOwned() + " of " + page.getTotal() + " slots", Theme.small(), Theme.TEXT_MUTED));
		for (String counter : page.getCounters())
		{
			text.add(Ui.label(counter, Theme.small(), Theme.TEXT));
		}
		head.add(text, BorderLayout.CENTER);
		stack.add(head);

		if (page.getLuck() != null)
		{
			Card dialCard = new Card(new BorderLayout());
			dialCard.setBorder(new EmptyBorder(8, 8, 8, 8));
			LuckDial dial = new LuckDial(104);
			dial.setLuck(page.getLuck(), false);
			dialCard.add(dial, BorderLayout.CENTER);
			dialCard.setToolTipText("An average player would own " + String.format("%.1f", page.getLuck().getExpected())
				+ " of these " + page.getLuck().getSlots() + " slots by now; you own " + page.getLuck().getOwned() + ".");
			stack.add(dialCard);
		}
		else if (!page.isComplete() && !page.isRead())
		{
			stack.add(Rows.note("Open this page in your collection log to read its kill count and see your luck here.", 190));
		}

		if (!page.isComplete())
		{
			JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 6));
			tiles.setOpaque(false);
			tiles.add(new StatTile(Format.hours(page.getHoursToNext()), "Next slot",
				page.getNextSource() == null ? "no rates" : Format.source(page.getNextSource()), Theme.TEAL));
			String finishNote = page.getUnrated() > 0 ? "+" + page.getUnrated() + " unrated" : "whole page";
			tiles.add(new StatTile(Format.hours(page.getHoursToFinish()), "To finish", finishNote, Theme.EMBER));
			stack.add(tiles);
		}

		List<Report.ItemReport> missing = new ArrayList<>();
		List<Report.ItemReport> owned = new ArrayList<>();
		for (Report.ItemReport item : page.getItems())
		{
			(item.isOwned() ? owned : missing).add(item);
		}
		if (!missing.isEmpty())
		{
			missing.sort(Comparator.comparingDouble(PageView::dryOrder));
			stack.add(new SectionHeader("Still to find", String.valueOf(missing.size())));
			for (Report.ItemReport item : missing)
			{
				stack.add(missingRow(item, icons, false, page.getNextSource()));
			}
		}
		if (!owned.isEmpty())
		{
			stack.add(new SectionHeader("Found", String.valueOf(owned.size())));
			stack.add(grid(owned, icons));
		}
		return stack;
	}

	/** Missing slots with a known dry chance first, driest at the top. */
	private static double dryOrder(Report.ItemReport item)
	{
		return item.getDryChance() < 0 ? 2 + (Double.isFinite(item.getHours()) ? 0 : 1) : item.getDryChance();
	}

	static JPanel grid(List<Report.ItemReport> items, ItemIcons icons)
	{
		JPanel grid = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
		grid.setOpaque(false);
		for (Report.ItemReport item : items)
		{
			grid.add(new ItemTile(item, icons));
		}
		for (int i = items.size(); i % COLUMNS != 0; i++)
		{
			JPanel filler = new JPanel();
			filler.setOpaque(false);
			grid.add(filler);
		}
		return grid;
	}

	/** A missing slot: its odds at your count, how dry you are, and where and how soon it comes alone. */
	static Card missingRow(Report.ItemReport item, ItemIcons icons, boolean withPage)
	{
		return missingRow(item, icons, withPage, null);
	}

	/** @param pageSource the activity the page is mostly hunted at, so its own slots just say "alone" */
	static Card missingRow(Report.ItemReport item, ItemIcons icons, boolean withPage, String pageSource)
	{
		StringBuilder detail = new StringBuilder(Format.chance(item.getChance()));
		if (item.getCount() >= 0)
		{
			detail.append(" at ").append(Format.count(item.getCount())).append(" kc");
		}
		String where = null;
		if (item.getSource() != null && Double.isFinite(item.getHours()))
		{
			where = item.getSource().equals(pageSource)
				? Format.about(item.getHours()) + " on its own"
				: Format.about(item.getHours()) + "  ·  " + Format.source(item.getSource());
		}
		if (withPage && item.getPage() != null)
		{
			where = item.getPage() + (where == null ? "" : "  ·  " + Format.about(item.getHours()));
		}
		Pill dry = null;
		if (item.getDryChance() >= 0)
		{
			dry = new Pill(Format.dry(item.getDryChance()), Theme.dry(item.getDryChance()));
		}
		Card card = Rows.line(new IconBadge(item.getItemId(), icons, false), item.getName(), detail.toString(), where,
			Theme.TEXT_FAINT, dry, item.getDryChance() >= 0 && item.getDryChance() < 0.2 ? Theme.dry(item.getDryChance()) : null);
		card.setToolTipText(ItemTile.tooltip(item));
		return card;
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tag, such as "Opens 12 more" or "Master". */
public class Pill extends JComponent
{
	private final String text;
	private final Color color;

	public Pill(String text, Color color)
	{
		this.text = text;
		this.color = color;
		setFont(Theme.small());
		setOpaque(false);
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 12, fm.getHeight() + 3);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, h, h);
		g.setColor(Theme.alpha(color, 34));
		g.fill(shape);
		g.setColor(Theme.alpha(color, 120));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(color);
		g.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent()) / 2 - 1);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A slim rounded bar that fills with the same ember-to-teal ramp as the rings. */
public class ProgressBar extends JComponent
{
	private final Animator animator = new Animator(this);
	private boolean complete;

	public ProgressBar(int height)
	{
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float arc = h;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
		double value = animator.get();
		if (value > 0)
		{
			float fill = (float) Math.max(h, w * value);
			if (complete)
			{
				g.setColor(Theme.GREEN);
			}
			else
			{
				g.setPaint(new GradientPaint(0, 0, Theme.progressColor(0), w, 0, Theme.progressColor(1)));
			}
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, arc, arc));
			g.setColor(Theme.alpha(java.awt.Color.WHITE, 40));
			g.drawLine(Math.round(arc / 2), 0, Math.round(fill - arc / 2), 0);
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, arc, arc));
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/** A gilded progress ring with the percentage set in the game's bold font. */
public class ProgressRing extends JComponent
{
	private final int diameter;
	private final float thickness;
	private final Animator animator = new Animator(this);
	private String caption;
	private boolean complete;

	public ProgressRing(int diameter, float thickness)
	{
		this.diameter = diameter;
		this.thickness = thickness;
		Dimension size = new Dimension(diameter, diameter);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	/** A small line under the percentage, for rings large enough to hold it. */
	public void setCaption(String caption)
	{
		this.caption = caption;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		double value = animator.get();
		float inset = thickness / 2f + 1;
		float size = diameter - inset * 2;

		// Inner well: a faint radial glow tinted by progress.
		Color glow = complete ? Theme.GREEN : Theme.progressColor(value);
		float r = size / 2f;
		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, r,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(glow, 40), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 200));
		g.draw(new Arc2D.Float(inset, inset, size, size, 0, 360, Arc2D.OPEN));

		if (value > 0)
		{
			g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			// Draw the arc in short segments so its colour can travel from ember to teal.
			int segments = Math.max(1, (int) Math.ceil(value * 72));
			double sweep = value * 360 / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(complete ? Theme.GREEN : Theme.progressColor(t));
				g.draw(new Arc2D.Double(inset, inset, size, size, 90 - i * sweep, -sweep - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}

		// Fine gold rim outside the track.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(diameter >= 48 ? Theme.title() : Theme.small());
		String text = Math.round(value * 100) + "%";
		FontMetrics fm = g.getFontMetrics();
		if (complete)
		{
			drawCheck(g, diameter / 2f, diameter / 2f - (caption != null && diameter >= 60 ? 5 : 0), diameter * 0.16f);
			text = null;
		}
		int textY = diameter / 2 + fm.getAscent() / 2 - 2;
		if (caption != null && diameter >= 60)
		{
			textY -= 5;
		}
		if (text != null)
		{
			drawShadowed(g, text, (diameter - fm.stringWidth(text)) / 2, textY, Theme.TEXT);
		}

		if (caption != null && diameter >= 60)
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			drawShadowed(g, caption, (diameter - small.stringWidth(caption)) / 2, textY + small.getAscent() + 1, Theme.TEXT_MUTED);
		}
		g.dispose();
	}

	/** A drawn check mark, since the game fonts have no glyph for one. */
	static void drawCheck(Graphics2D g, float cx, float cy, float r)
	{
		java.awt.geom.Path2D check = new java.awt.geom.Path2D.Float();
		check.moveTo(cx - r, cy);
		check.lineTo(cx - r * 0.3f, cy + r * 0.7f);
		check.lineTo(cx + r, cy - r * 0.65f);
		g.setStroke(new BasicStroke(Math.max(1.6f, r * 0.32f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GREEN);
		g.draw(check);
	}

	static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import com.codex.loginsight.data.Activity;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every activity ranked by the expected wait for its next new slot. */
final class QuarryView
{
	static final String[] FILTERS = {"All", "Combat", "Games", "Other", "Pets"};
	private static final int SHOWN = 40;

	private QuarryView()
	{
	}

	static StackPanel build(Report report, int filter, ItemIcons icons)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to rank where your next slots will come from.", 190));
			return stack;
		}
		boolean pets = filter == 4;
		stack.add(Rows.note((pets ? "Ranked by the wait for a pet" : "Ranked by the wait for a new slot")
			+ (report.isIronRates() ? " at ironman rates" : " at typical rates")
			+ ". Activities you do often switch to your own pace; ones you cannot do yet come last.", 190));
		List<Report.Hunt> hunts = new ArrayList<>();
		for (Report.Hunt hunt : report.getHunts())
		{
			if (matches(hunt, filter))
			{
				hunts.add(hunt);
			}
		}
		if (pets)
		{
			hunts.sort(Comparator.comparing((Report.Hunt h) -> h.getLockedBy() != null)
				.thenComparingDouble(Report.Hunt::getHoursToPet));
		}
		int rank = 0;
		for (Report.Hunt hunt : hunts)
		{
			rank++;
			stack.add(row(hunt, rank, icons, pets));
			if (rank >= SHOWN)
			{
				break;
			}
		}
		if (rank == 0)
		{
			stack.add(Rows.note("Nothing left to hunt here.", 190));
		}
		return stack;
	}

	private static boolean matches(Report.Hunt hunt, int filter)
	{
		switch (filter)
		{
			case 1:
				return hunt.getCategory() == Activity.Category.COMBAT;
			case 2:
				return hunt.getCategory() == Activity.Category.MINIGAME;
			case 3:
				return hunt.getCategory() == Activity.Category.OTHER;
			case 4:
				return hunt.isPet();
			default:
				return true;
		}
	}

	static Card row(Report.Hunt hunt, int rank, ItemIcons icons)
	{
		return row(hunt, rank, icons, false);
	}

	/** @param pets lead with the wait for this activity's pet rather than its next slot */
	static Card row(Report.Hunt hunt, int rank, ItemIcons icons, boolean pets)
	{
		boolean locked = hunt.getLockedBy() != null;
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (rank == 1 && !locked)
		{
			card.accent(Theme.TEAL);
		}
		JPanel lead = new JPanel(new BorderLayout());
		lead.setOpaque(false);
		lead.add(new Rank(rank, locked), BorderLayout.NORTH);
		card.add(lead, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.clamped(Format.source(hunt.getName()), Theme.body(), locked ? Theme.TEXT_MUTED : Theme.TEXT, 118, 2));
		String detail = Format.detail(hunt.getName());
		if (detail != null && !detail.isEmpty())
		{
			text.add(Ui.clamped(detail, Theme.small(), Theme.GOLD_DIM, 118, 1));
		}
		if (locked)
		{
			text.add(Ui.clamped("Needs " + hunt.getLockedBy(), Theme.small(), Theme.EMBER, 118, 1));
		}
		if (pets && hunt.getPetName() != null)
		{
			text.add(Ui.label("Pet " + Format.about(hunt.getHoursToPet()) + "  ·  " + hunt.getRemaining() + " left",
				Theme.small(), Theme.VIOLET));
		}
		else
		{
			text.add(Ui.label("Next " + Format.about(hunt.getHoursToNext()) + "  ·  " + hunt.getRemaining() + " left",
				Theme.small(), locked ? Theme.TEXT_MUTED : Theme.TEAL));
		}
		String next = "";
		if (hunt.getNextItemName() != null)
		{
			long after = Math.round(1 / hunt.getNextChance());
			next = hunt.getNextItemName() + (hunt.isNextEarned()
				? (after <= 1 ? ", every time" : ", earned in " + Format.count(after))
				: " " + Format.chance(hunt.getNextChance()));
		}
		if (pets && hunt.getPetName() != null)
		{
			next = hunt.getPetName();
		}
		JLabel nextLabel = Ui.label(next, Theme.small(), Theme.TEXT_MUTED);
		nextLabel.setToolTipText(next);
		text.add(nextLabel);
		text.add(Ui.label("All " + hunt.getRemaining() + " " + Format.about(hunt.getHoursToFinish())
			+ (hunt.isOwnPace() ? "  ·  your pace" : ""), Theme.small(), hunt.isOwnPace() ? Theme.GOLD : Theme.TEXT_FAINT));
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);

		int shown = pets && hunt.getPetItemId() > 0 ? hunt.getPetItemId() : hunt.getNextItemId();
		if (shown > 0)
		{
			JPanel trail = new JPanel(new BorderLayout());
			trail.setOpaque(false);
			trail.add(new IconBadge(shown, icons, false), BorderLayout.NORTH);
			card.add(trail, BorderLayout.EAST);
		}
		card.setToolTipText("<html>" + Ui.escape(hunt.getName()) + "<br>" + Math.round(hunt.getPerHour()) + " per hour"
			+ (hunt.isOwnPace() ? " (your pace)" : "") + "</html>");
		return card;
	}

	/** A small gilt medallion with the rank number. */
	private static final class Rank extends JComponent
	{
		private final int rank;
		private final boolean locked;

		Rank(int rank, boolean locked)
		{
			this.rank = rank;
			this.locked = locked;
			Dimension d = new Dimension(20, 20);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			boolean first = rank <= 3 && !locked;
			g.setColor(first ? Theme.alpha(Theme.GOLD, 60) : Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(1, 1, 18, 18));
			g.setColor(first ? Theme.GOLD : Theme.STROKE);
			g.draw(new Ellipse2D.Float(1, 1, 18, 18));
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = String.valueOf(rank);
			ProgressRing.drawShadowed(g, text, 10 - fm.stringWidth(text) / 2, 10 + fm.getAscent() / 2 - 1,
				first ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);
			g.dispose();
		}
	}
}

package com.codex.loginsight.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Compact card lines: a verdict mark, a name, a quiet second line and an optional value. */
public final class Rows
{
	private Rows()
	{
	}

	public static Card check(Mark.Kind kind, String title, String detail, String value)
	{
		return line(new Mark(kind, 14), title, detail, value == null ? null : Ui.label(value, Theme.small(), Mark.color(kind)),
			kind == Mark.Kind.BAD ? Theme.BLOOD : null);
	}

	/** A verdict with a sentence that may run to two lines. */
	public static Card reason(Mark.Kind kind, String text)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (kind == Mark.Kind.BAD)
		{
			card.accent(Theme.BLOOD);
		}
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(1, 0, 0, 0));
		holder.add(new Mark(kind, 14), BorderLayout.NORTH);
		card.add(holder, BorderLayout.WEST);
		card.add(Ui.wrapped(text, Theme.body(), Theme.TEXT, 160), BorderLayout.CENTER);
		return card;
	}

	public static Card line(JComponent lead, String title, String detail, JComponent trailing, Color accent)
	{
		return line(lead, title, detail, null, null, trailing, accent);
	}

	/** As {@link #line}, with a third line in its own colour, such as a verdict or where to go. */
	public static Card line(JComponent lead, String title, String detail, String extra, Color extraColor,
		JComponent trailing, Color accent)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (accent != null)
		{
			card.accent(accent);
		}
		if (lead != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.setBorder(new EmptyBorder(1, 0, 0, 0));
			holder.add(lead, BorderLayout.NORTH);
			card.add(holder, BorderLayout.WEST);
		}
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JLabel name = Ui.label(title, Theme.body(), Theme.TEXT);
		name.setToolTipText(title);
		if (trailing != null)
		{
			// The tag sits beside the name only, so the lines under it keep the card's full width.
			JPanel top = new JPanel(new BorderLayout(6, 0));
			top.setOpaque(false);
			name.setMinimumSize(new Dimension(10, name.getPreferredSize().height));
			name.setPreferredSize(new Dimension(10, Math.max(name.getPreferredSize().height, trailing.getPreferredSize().height)));
			top.add(name, BorderLayout.CENTER);
			top.add(trailing, BorderLayout.EAST);
			top.setAlignmentX(Component.LEFT_ALIGNMENT);
			text.add(top);
		}
		else
		{
			text.add(name);
		}
		if (detail != null && !detail.isEmpty())
		{
			JLabel sub = Ui.label(detail, Theme.small(), Theme.TEXT_MUTED);
			sub.setToolTipText(detail);
			text.add(sub);
		}
		if (extra != null && !extra.isEmpty())
		{
			JLabel third = Ui.label(extra, Theme.small(), extraColor == null ? Theme.TEXT_FAINT : extraColor);
			third.setToolTipText(extra);
			text.add(third);
		}
		// Long names clip with an ellipsis rather than push the value off the card.
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);
		return card;
	}

	/** A quiet line of text for empty states. */
	public static JComponent note(String text, int width)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(2, 4, 2, 4));
		holder.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, width), BorderLayout.CENTER);
		return holder;
	}
}

package com.codex.loginsight.ui;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JScrollBar;
import javax.swing.plaf.basic.BasicScrollBarUI;

/** A slim gilt scrollbar on an ink track, in place of the look-and-feel's bright default. */
final class Scrollbars extends BasicScrollBarUI
{
	static final int WIDTH = 7;

	static void style(JScrollBar bar)
	{
		bar.setUI(new Scrollbars());
		bar.setOpaque(false);
		bar.setPreferredSize(new Dimension(WIDTH, 0));
		bar.setUnitIncrement(16);
	}

	@Override
	protected JButton createDecreaseButton(int orientation)
	{
		return none();
	}

	@Override
	protected JButton createIncreaseButton(int orientation)
	{
		return none();
	}

	private static JButton none()
	{
		JButton button = new JButton();
		Dimension zero = new Dimension(0, 0);
		button.setPreferredSize(zero);
		button.setMinimumSize(zero);
		button.setMaximumSize(zero);
		return button;
	}

	@Override
	protected void paintTrack(Graphics graphics, JComponent c, Rectangle r)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setColor(Theme.alpha(Theme.INK_DEEP, 160));
		g.fill(new RoundRectangle2D.Float(r.x + 2, r.y + 2, r.width - 4, r.height - 4, 3, 3));
		g.dispose();
	}

	@Override
	protected void paintThumb(Graphics graphics, JComponent c, Rectangle r)
	{
		if (r.isEmpty() || !scrollbar.isEnabled())
		{
			return;
		}
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setColor(isThumbRollover() || isDragging ? Theme.GOLD : Theme.GOLD_DIM);
		g.fill(new RoundRectangle2D.Float(r.x + 1, r.y + 1, r.width - 2, r.height - 2, r.width - 2, r.width - 2));
		g.dispose();
	}
}

